      "text": "Homem de 65 anos queixa-se de claudicação intermitente há 6 meses, com piora da dor em membro inferior direito há 25 dias, ao caminhar cerca de 30 metros e aliviada com repouso. AP: ex-tabagista há 10 anos, DM2 em uso de metformina. Exame físico: pulsos femorais presentes bilateralmente, ausência de pulsos poplíteos, tibiais posteriores e tibiais anteriores bilateralmente. Em face do exposto, a conduta deve ser:",
