      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 1. Sem revisão clínica independente.",
      "officialComment": "Claudicação que limita a marcha a 30 metros, com piora rápida em 25 dias, em diabético ex-tabagista, é claudicação incapacitante, já no limiar da isquemia crítica. O exame localiza a doença: pulsos femorais presentes e ausência de poplíteos e distais indicam obstrução femoropoplítea bilateral. Claudicação incapacitante, dor em repouso e lesões tróficas são indicações de revascularização, e o primeiro passo é definir a anatomia com angiografia (ou angiotomografia) para escolher entre cirurgia aberta e endovascular. Caminhada supervisionada com analgesia (B) e cilostazol com reabilitação (C) são o tratamento da claudicação estável, leve a moderada, e não cabem diante de incapacidade progressiva. A angioplastia ilíaca (D) erra o segmento: com pulso femoral presente, a lesão é infrainguinal, e nenhuma técnica deve ser escolhida antes do estudo de imagem.",
      "explanation": "Claudicação que limita a marcha a 30 metros, com piora rápida em 25 dias, em diabético ex-tabagista, é claudicação incapacitante, já no limiar da isquemia crítica. O exame localiza a doença: pulsos femorais presentes e ausência de poplíteos e distais indicam obstrução femoropoplítea bilateral. Claudicação incapacitante, dor em repouso e lesões tróficas são indicações de revascularização, e o primeiro passo é definir a anatomia com angiografia (ou angiotomografia) para escolher entre cirurgia aberta e endovascular. Caminhada supervisionada com analgesia (B) e cilostazol com reabilitação (C) são o tratamento da claudicação estável, leve a moderada, e não cabem diante de incapacidade progressiva. A angioplastia ilíaca (D) erra o segmento: com pulso femoral presente, a lesão é infrainguinal, e nenhuma técnica deve ser escolhida antes do estudo de imagem.",
