      "text": "Paciente do sexo masculino, 56 anos, procura atendimento para realização de \"check- up\". Refere histórico de gota, em uso atualmente de colchicina devido à crise álgica. Refere etilismo aos finais de semana, de 2 a 3 latas de cerveja, e nega tabagismo e uso de drogas ilícitas. É sedentário e relata alta ingesta de alimentos ultraprocessados. Ao exame físico, está em bom estado geral, corado e hidratado; lúcido e orientado em tempo e espaço. Aparelho respiratório: murmúrio vesicular presente, sem ruídos adventícios, SPO2 96%. Aparelho cardiovascular: bulhas rítmicas normofonéticas, em 2 tempos, sem sopros audíveis FC 103 bpm PA: 140x90 mmHg. Abdome: globoso, flácido, sem massas ou visceromegalias palpáveis. Extremidades: bem perfundidas sem exames. Peso: 96 kg. Altura: 1,70 m. Circunferência abdominal: 115 cm. A conduta mais adequada para esse paciente nesse momento é",
      "statement": "Paciente do sexo masculino, 56 anos, procura atendimento para realização de \"check- up\". Refere histórico de gota, em uso atualmente de colchicina devido à crise álgica. Refere etilismo aos finais de semana, de 2 a 3 latas de cerveja, e nega tabagismo e uso de drogas ilícitas. É sedentário e relata alta ingesta de alimentos ultraprocessados. Ao exame físico, está em bom estado geral, corado e hidratado; lúcido e orientado em tempo e espaço. Aparelho respiratório: murmúrio vesicular presente, sem ruídos adventícios, SPO2 96%. Aparelho cardiovascular: bulhas rítmicas normofonéticas, em 2 tempos, sem sopros audíveis FC 103 bpm PA: 140x90 mmHg. Abdome: globoso, flácido, sem massas ou visceromegalias palpáveis. Extremidades: bem perfundidas sem exames. Peso: 96 kg. Altura: 1,70 m. Circunferência abdominal: 115 cm. A conduta mais adequada para esse paciente nesse momento é",
