      "officialComment": "A pressão de 140 por 90 em uma única consulta corresponde, se confirmada, a hipertensão estágio 1, em paciente sem diabetes, sem lesão de órgão-alvo e sem doença cardiovascular. A diretriz brasileira orienta confirmar o diagnóstico em nova aferição, MAPA ou MRPA e, no estágio 1 com risco cardiovascular baixo ou moderado, tentar de três a seis meses de mudança de estilo de vida antes de medicar: perda de peso, dieta, atividade física e redução do álcool, com reavaliação em 3 meses. Além disso, a hidroclorotiazida (A) eleva o ácido úrico e é contraindicada em gota, e o atenolol (C) não é primeira linha. A losartana (B) seria a escolha se e quando houver indicação de fármaco.",
      "explanation": "A pressão de 140 por 90 em uma única consulta corresponde, se confirmada, a hipertensão estágio 1, em paciente sem diabetes, sem lesão de órgão-alvo e sem doença cardiovascular. A diretriz brasileira orienta confirmar o diagnóstico em nova aferição, MAPA ou MRPA e, no estágio 1 com risco cardiovascular baixo ou moderado, tentar de três a seis meses de mudança de estilo de vida antes de medicar: perda de peso, dieta, atividade física e redução do álcool, com reavaliação em 3 meses. Além disso, a hidroclorotiazida (A) eleva o ácido úrico e é contraindicada em gota, e o atenolol (C) não é primeira linha. A losartana (B) seria a escolha se e quando houver indicação de fármaco.",
