      "text": "Um homem de 64 anos de idade, saudável, agricultor, apresentase no consultório com uma lesão cutânea que ele notou há cerca de 6 meses. A lesão está localizada no dorso da mão direita e tem crescido lentamente. O paciente relata que área está um pouco dolorosa e pruriginosa. Ao exame físico, observa-se uma lesão de 1,2 cm de diâmetro, de cor acastanhada, bordas irregulares, e com algumas áreas de ulceração, e há linfadenomegalia palpável na axila. Com base na descrição clínica e no exame físico, as melhores propostas diagnósticas e terapêuticas para esse paciente são, respectivamente:",
      "statement": "Um homem de 64 anos de idade, saudável, agricultor, apresentase no consultório com uma lesão cutânea que ele notou há cerca de 6 meses. A lesão está localizada no dorso da mão direita e tem crescido lentamente. O paciente relata que área está um pouco dolorosa e pruriginosa. Ao exame físico, observa-se uma lesão de 1,2 cm de diâmetro, de cor acastanhada, bordas irregulares, e com algumas áreas de ulceração, e há linfadenomegalia palpável na axila. Com base na descrição clínica e no exame físico, as melhores propostas diagnósticas e terapêuticas para esse paciente são, respectivamente:",
