      "officialComment": "Lesão pigmentada acastanhada com bordas irregulares, ulceração, crescimento em seis meses e linfonodo axilar palpável em agricultor exposto ao sol preenche os critérios ABCDE e sugere melanoma já com possível disseminação regional. A conduta é biópsia excisional com margem estreita e, confirmado o diagnóstico, ampliação de margens conforme o Breslow e avaliação do linfonodo palpável por punção ou biópsia, com linfadenectomia se positivo. O carcinoma espinocelular (A) é lesão queratósica ou ulcerada eritematosa, e curetagem com eletrocoagulação não seria tratamento adequado para lesão invasiva. Queratoacantoma (C) cresce em semanas com cratera central e não se trata com antibiótico. Dermatofibroma (B) é pápula firme e benigna que não ulcera.",
