      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 31. Sem revisão clínica independente.",
      "officialComment": "Prurido generalizado há 7 meses, sem lesões cutâneas primárias além de escoriações e xerose leve, com hemograma, função renal, hepática e colestase normais, afasta as principais causas sistêmicas. Sobra o medicamento: opioides como o tramadol causam prurido por ação central nos receptores mu, independente de histamina, e a conduta racional é substituir o fármaco por analgésicos simples e observar. Anti-histamínico (C) tem pouca eficácia em prurido não histaminérgico. Gabapentina e pregabalina (D) são segunda linha, para prurido neuropático ou urêmico. Hidratação e corticoide tópico (A) aliviam a xerose, mas não tratam a causa.",
