      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 86. Sem revisão clínica independente.",
      "officialComment": "Mulher de 65 anos com diabetes tipo 2 e relação albumina/creatinina de 210 mg/g, sem doença aterosclerótica estabelecida, com edema de membros inferiores frio, mole e indolor iniciado depois do anlodipino. O edema é efeito adverso clássico do bloqueador de canal de cálcio diidropiridínico, que deve ser substituído. A albuminúria em diabético indica inibidor de SGLT2, que reduz a progressão renal e os eventos cardiovasculares, mantendo a losartana, que também protege o rim. O AAS em prevenção primária, em paciente idosa sem doença aterosclerótica, aumenta sangramento sem benefício claro e deve ser suspenso. Trocar a losartana (C e D) retira a nefroproteção; manter o AAS (B) contraria a evidência atual, ainda que a semaglutida também tenha benefício renal.",
      "explanation": "Mulher de 65 anos com diabetes tipo 2 e relação albumina/creatinina de 210 mg/g, sem doença aterosclerótica estabelecida, com edema de membros inferiores frio, mole e indolor iniciado depois do anlodipino. O edema é efeito adverso clássico do bloqueador de canal de cálcio diidropiridínico, que deve ser substituído. A albuminúria em diabético indica inibidor de SGLT2, que reduz a progressão renal e os eventos cardiovasculares, mantendo a losartana, que também protege o rim. O AAS em prevenção primária, em paciente idosa sem doença aterosclerótica, aumenta sangramento sem benefício claro e deve ser suspenso. Trocar a losartana (C e D) retira a nefroproteção; manter o AAS (B) contraria a evidência atual, ainda que a semaglutida também tenha benefício renal.",
