      "edition": "tpi-2026-2-tpi2",
      "text": "Um homem de 52 anos, IMC: 30,2 kg/m2, histórico familiar de diabetes tipo 2, apresenta glicemia de jejum de 112 mg/dL e HbA1c de 6,0%, configurando pré-diabetes. Ele relata falha em atingir perda ponderal significativa após 6 meses de intervenção com dieta e exercício supervisionados. Considerando a evidência atual e as diretrizes internacionais sobre o uso de análogos do GLP-1 nesse contexto, qual é a conduta mais adequada?",
      "statement": "Um homem de 52 anos, IMC: 30,2 kg/m2, histórico familiar de diabetes tipo 2, apresenta glicemia de jejum de 112 mg/dL e HbA1c de 6,0%, configurando pré-diabetes. Ele relata falha em atingir perda ponderal significativa após 6 meses de intervenção com dieta e exercício supervisionados. Considerando a evidência atual e as diretrizes internacionais sobre o uso de análogos do GLP-1 nesse contexto, qual é a conduta mais adequada?",
      "opts": [
        "Postergar o análogo de GLP-1 até paciente preencher critérios para DM2, pois o seu papel preventivo ainda é controverso no pré-diabetes na ausência de complicações metabólicas adicionais.",
        "Indicar GLP-1 apenas em casos de pré-diabetes associados a doença cardiovascular aterosclerótica documentada, pois o seu benefício está restrito à proteção macrovascular.",
        "Considerar o análogo de GLP-1 como adjuvante no pré-diabetes com obesidade após falha de intervenção no estilo de vida, visando a perda de peso e prevenção da progressão do diabetes.",
        "Evitar o uso de análogo de GLP-1 em pacientes no pré-diabetes com o objetivo de controle metabólico, pois não há evidência de redução na incidência de diabetes tipo 2 nesse grupo."
      ],
      "alternatives": [
        "Postergar o análogo de GLP-1 até paciente preencher critérios para DM2, pois o seu papel preventivo ainda é controverso no pré-diabetes na ausência de complicações metabólicas adicionais.",
        "Indicar GLP-1 apenas em casos de pré-diabetes associados a doença cardiovascular aterosclerótica documentada, pois o seu benefício está restrito à proteção macrovascular.",
        "Considerar o análogo de GLP-1 como adjuvante no pré-diabetes com obesidade após falha de intervenção no estilo de vida, visando a perda de peso e prevenção da progressão do diabetes.",
        "Evitar o uso de análogo de GLP-1 em pacientes no pré-diabetes com o objetivo de controle metabólico, pois não há evidência de redução na incidência de diabetes tipo 2 nesse grupo."
      ],
      "answer": "C",
