      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 54. Sem revisão clínica independente.",
      "officialComment": "Pré-diabetes com obesidade grau 1 e falha de seis meses de dieta e exercício supervisionados. Os análogos de GLP-1 (liraglutida 3 mg, semaglutida 2,4 mg) estão indicados para tratamento da obesidade com IMC de 30 ou mais, e os ensaios SCALE e STEP mostraram, além da perda de peso, redução da progressão para diabetes tipo 2 e reversão para normoglicemia. Por isso a diretriz aceita considerálos como adjuvantes nesse contexto. A alternativa B restringe a indicação à doença aterosclerótica, o que vale para a decisão em diabéticos, não para o tratamento da obesidade. As alternativas A e D negam evidência já disponível. A metformina segue como opção de baixo custo.",
      "explanation": "Pré-diabetes com obesidade grau 1 e falha de seis meses de dieta e exercício supervisionados. Os análogos de GLP-1 (liraglutida 3 mg, semaglutida 2,4 mg) estão indicados para tratamento da obesidade com IMC de 30 ou mais, e os ensaios SCALE e STEP mostraram, além da perda de peso, redução da progressão para diabetes tipo 2 e reversão para normoglicemia. Por isso a diretriz aceita considerálos como adjuvantes nesse contexto. A alternativa B restringe a indicação à doença aterosclerótica, o que vale para a decisão em diabéticos, não para o tratamento da obesidade. As alternativas A e D negam evidência já disponível. A metformina segue como opção de baixo custo.",
