      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 15. Sem revisão clínica independente.",
      "officialComment": "Pelo ACR TI-RADS somam-se pontos por composição, ecogenicidade, forma, margens e focos ecogênicos: sólido (2), hipoecoico (2), mais largo que alto (0), margens irregulares (2) e microcalcificações (3) dão 9 pontos, categoria TR5 (7 pontos ou mais), altamente suspeita. Para TR5 a punção aspirativa por agulha fina é indicada a partir de 1,0 cm, e o nódulo tem 1,3 cm. TR3 (A) corresponde a 3 pontos e TR4 (C) a 4 a 6. Indicar cirurgia sem citologia (D) é errado: o resultado de Bethesda é que define a conduta.",
      "explanation": "Pelo ACR TI-RADS somam-se pontos por composição, ecogenicidade, forma, margens e focos ecogênicos: sólido (2), hipoecoico (2), mais largo que alto (0), margens irregulares (2) e microcalcificações (3) dão 9 pontos, categoria TR5 (7 pontos ou mais), altamente suspeita. Para TR5 a punção aspirativa por agulha fina é indicada a partir de 1,0 cm, e o nódulo tem 1,3 cm. TR3 (A) corresponde a 3 pontos e TR4 (C) a 4 a 6. Indicar cirurgia sem citologia (D) é errado: o resultado de Bethesda é que define a conduta.",
