      "text": "Homem de 55 anos, com história de dor e aumento do volume abdominal há trinta dias, associada à anorexia e piora do quadro abdominal. Nega febre e, no exame físico, não há instabilidade hemodinâmica. Apresenta confusão mental, flapping, dor abdominal discreta e ascite, sendo difícil a avaliação de visceromegalias. Os exames laboratoriais do paciente indicam hemoglobina = 10g/dL, leucócitos = 9.000/mm3, plaquetas = 90.000/mm3, ureia = 48mg/dL, creatinina = 1,2mg/dL, proteína total = 6g/dL e albumina = 3g/dL. A punção do líquido ascítico mostra celularidade de 600células/mm3, sendo 40% mononucleares, glicose = 45mg/dL, proteína total = 2g/dL, albumina = 1g/dL e LDH = 90UI/L (valor normal na ascite 45UI/L), sendo solicitados TC de abdômen, Gram e cultura do líquido ascítico. Nesse caso, a melhor conduta é:",
      "statement": "Homem de 55 anos, com história de dor e aumento do volume abdominal há trinta dias, associada à anorexia e piora do quadro abdominal. Nega febre e, no exame físico, não há instabilidade hemodinâmica. Apresenta confusão mental, flapping, dor abdominal discreta e ascite, sendo difícil a avaliação de visceromegalias. Os exames laboratoriais do paciente indicam hemoglobina = 10g/dL, leucócitos = 9.000/mm3, plaquetas = 90.000/mm3, ureia = 48mg/dL, creatinina = 1,2mg/dL, proteína total = 6g/dL e albumina = 3g/dL. A punção do líquido ascítico mostra celularidade de 600células/mm3, sendo 40% mononucleares, glicose = 45mg/dL, proteína total = 2g/dL, albumina = 1g/dL e LDH = 90UI/L (valor normal na ascite 45UI/L), sendo solicitados TC de abdômen, Gram e cultura do líquido ascítico. Nesse caso, a melhor conduta é:",
