      "officialComment": "Cirrótico com ascite, encefalopatia e líquido ascítico com 600 células por mm3, 60% de polimorfonucleares, isto é, 360 polimorfonucleares por mm3, acima de 250, tem peritonite bacteriana espontânea. O antibiótico, cefalosporina de terceira geração, começa imediatamente, sem esperar cultura ou tomografia. A albumina intravenosa, 1,5 g/kg no primeiro dia e 1 g/kg no terceiro, reduz a síndrome hepatorrenal e a mortalidade e está indicada sobretudo quando ureia passa de 30 mg/dL, creatinina de 1 ou bilirrubina de 4, e aqui a ureia é de 48. O betabloqueador (B) não tem papel na PBE aguda e pode piorar a hemodinâmica. Aguardar cultura (A) ou tomografia (C) atrasa o tratamento.",
      "explanation": "Cirrótico com ascite, encefalopatia e líquido ascítico com 600 células por mm3, 60% de polimorfonucleares, isto é, 360 polimorfonucleares por mm3, acima de 250, tem peritonite bacteriana espontânea. O antibiótico, cefalosporina de terceira geração, começa imediatamente, sem esperar cultura ou tomografia. A albumina intravenosa, 1,5 g/kg no primeiro dia e 1 g/kg no terceiro, reduz a síndrome hepatorrenal e a mortalidade e está indicada sobretudo quando ureia passa de 30 mg/dL, creatinina de 1 ou bilirrubina de 4, e aqui a ureia é de 48. O betabloqueador (B) não tem papel na PBE aguda e pode piorar a hemodinâmica. Aguardar cultura (A) ou tomografia (C) atrasa o tratamento.",
