      "edition": "tpi-2026-2-tpi2",
      "text": "Homem, 48 anos de idade, morador de área livre, foi internado com quadro de uma semana de confusão mental e diarreia, evacuando fezes aquosas várias vezes ao dia com urgência. Ele estava confuso e desorientado em relação ao espaço e ao tempo. Relata ingerir aproximadamente 100 mL de destilado por dia. Exame físico: alerta, confuso, exame neurológico normal e sem nistagmo ou oftalmoplegia; dentes em mau estado de conservação; erupção cutânea eritematosa, simétrica e sem coceira, predominantemente na face, pescoço, mãos e antebraços, com algumas bolhas. Qual é a deficiência nutricional mais provável?",
      "statement": "Homem, 48 anos de idade, morador de área livre, foi internado com quadro de uma semana de confusão mental e diarreia, evacuando fezes aquosas várias vezes ao dia com urgência. Ele estava confuso e desorientado em relação ao espaço e ao tempo. Relata ingerir aproximadamente 100 mL de destilado por dia. Exame físico: alerta, confuso, exame neurológico normal e sem nistagmo ou oftalmoplegia; dentes em mau estado de conservação; erupção cutânea eritematosa, simétrica e sem coceira, predominantemente na face, pescoço, mãos e antebraços, com algumas bolhas. Qual é a deficiência nutricional mais provável?",
