      "officialComment": "Diarreia, confusão mental e dermatite eritematosa simétrica e fotossensível em face, pescoço, mãos e antebraços, com bolhas, em etilista com má nutrição, formam a tríade da pelagra: dermatite, diarreia e demência, por deficiência de niacina (vitamina B3). A deficiência de tiamina (B) causa Wernicke, com oftalmoplegia, ataxia e nistagmo, aqui ausentes, ou beribéri. A deficiência de B12 (D) dá anemia megaloblástica, neuropatia e mielopatia. A de piridoxina (A) dá neuropatia periférica, glossite e dermatite seborreica, sem a fotossensibilidade típica. O tratamento é nicotinamida e correção nutricional global.",
      "explanation": "Diarreia, confusão mental e dermatite eritematosa simétrica e fotossensível em face, pescoço, mãos e antebraços, com bolhas, em etilista com má nutrição, formam a tríade da pelagra: dermatite, diarreia e demência, por deficiência de niacina (vitamina B3). A deficiência de tiamina (B) causa Wernicke, com oftalmoplegia, ataxia e nistagmo, aqui ausentes, ou beribéri. A deficiência de B12 (D) dá anemia megaloblástica, neuropatia e mielopatia. A de piridoxina (A) dá neuropatia periférica, glossite e dermatite seborreica, sem a fotossensibilidade típica. O tratamento é nicotinamida e correção nutricional global.",
