      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 40. Sem revisão clínica independente.",
      "officialComment": "Hematêmese em usuário crônico de analgésicos, com pressão de 80 por 45, taquicardia, sudorese e agitação, é hemorragia digestiva alta com choque hipovolêmico. O primeiro passo é o mesmo de qualquer choque hemorrágico: dois acessos venosos calibrosos, reposição volêmica e hemoderivados, inibidor de bomba de prótons intravenoso e proteção da via aérea se necessário; a endoscopia (D) vem em até 24 horas, após a estabilização. A lavagem gástrica com salina gelada (A) não é recomendada. A arteriografia com embolização (B) é o resgate quando a endoscopia falha.",
      "explanation": "Hematêmese em usuário crônico de analgésicos, com pressão de 80 por 45, taquicardia, sudorese e agitação, é hemorragia digestiva alta com choque hipovolêmico. O primeiro passo é o mesmo de qualquer choque hemorrágico: dois acessos venosos calibrosos, reposição volêmica e hemoderivados, inibidor de bomba de prótons intravenoso e proteção da via aérea se necessário; a endoscopia (D) vem em até 24 horas, após a estabilização. A lavagem gástrica com salina gelada (A) não é recomendada. A arteriografia com embolização (B) é o resgate quando a endoscopia falha.",
      "sourceCommentImported": true,
