      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 5. Sem revisão clínica independente.",
      "officialComment": "Fezes volumosas, oleosas, fétidas e que flutuam são esteatorreia; somadas à dor epigástrica irradiada ao dorso que piora após as refeições, ao emagrecimento de 8 kg e a mais de 20 anos de etilismo com tabagismo, apontam para pancreatite crônica com insuficiência exócrina. A confirmação vem da elastase fecal baixa e das calcificações pancreáticas na tomografia. A síndrome do intestino irritável (B) não causa perda de peso nem esteatorreia. O supercrescimento bacteriano (C) pode dar diarreia e má absorção, mas não explica a dor pancreática típica e o contexto etílico. A doença de Crohn jejunal (D) é rara nessa idade e cursaria com outros sinais inflamatórios. O tratamento é reposição de enzimas pancreáticas, abstinência de álcool e tabaco e controle da dor.",
      "explanation": "Fezes volumosas, oleosas, fétidas e que flutuam são esteatorreia; somadas à dor epigástrica irradiada ao dorso que piora após as refeições, ao emagrecimento de 8 kg e a mais de 20 anos de etilismo com tabagismo, apontam para pancreatite crônica com insuficiência exócrina. A confirmação vem da elastase fecal baixa e das calcificações pancreáticas na tomografia. A síndrome do intestino irritável (B) não causa perda de peso nem esteatorreia. O supercrescimento bacteriano (C) pode dar diarreia e má absorção, mas não explica a dor pancreática típica e o contexto etílico. A doença de Crohn jejunal (D) é rara nessa idade e cursaria com outros sinais inflamatórios. O tratamento é reposição de enzimas pancreáticas, abstinência de álcool e tabaco e controle da dor.",
