      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Homem, 38 anos, veio à consulta na UBS para avaliação de exames laboratoriais. Relatava história familiar de anemia com necessidade de tratamento. Hemograma completo: Hb: 15,7 g/dl (VR: 13,9 - 17,7 g/dl) VCM: 85 fl (VR: 80 - 95 fl); Glóbulos brancos: 8,8 x 103/μL (VR: 3,79 - 10,3 x 103/μL); Plaquetas: 230 x 103/μL (VR: 166 - 389 x103/ μL); Estudo de hemoglobina: S=38% (VR: 0%); A:59% (VR: 95 - 98%); A2: 2,3% (VR: 2,0 - 3,3%). Qual é a conduta mais adequada para o paciente neste momento?",
      "statement": "Homem, 38 anos, veio à consulta na UBS para avaliação de exames laboratoriais. Relatava história familiar de anemia com necessidade de tratamento. Hemograma completo: Hb: 15,7 g/dl (VR: 13,9 - 17,7 g/dl) VCM: 85 fl (VR: 80 - 95 fl); Glóbulos brancos: 8,8 x 103/μL (VR: 3,79 - 10,3 x 103/μL); Plaquetas: 230 x 103/μL (VR: 166 - 389 x103/ μL); Estudo de hemoglobina: S=38% (VR: 0%); A:59% (VR: 95 - 98%); A2: 2,3% (VR: 2,0 - 3,3%). Qual é a conduta mais adequada para o paciente neste momento?",
