      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 3. Sem revisão clínica independente.",
      "officialComment": "Eletroforese com hemoglobina S de 38%, hemoglobina A de 59% e A2 normal, em adulto com hemograma normal, define traço falciforme (HbAS), condição benigna que não é anemia falciforme. Não há indicação de hidroxiureia (C), reservada à doença falciforme com crises ou complicações, nem de Doppler transcraniano (A), rastreamento de acidente vascular em crianças com HbSS entre 2 e 16 anos. A análise molecular dos genes da alfa-globina (D) explicaria por que a fração S é um pouco abaixo de 40%, mas não muda nenhuma conduta. O que o portador precisa é de aconselhamento genético: se a parceira também for portadora de traço ou de outra hemoglobinopatia, há 25% de chance de um filho com doença falciforme, e o casal deve ser orientado e testado.",
      "explanation": "Eletroforese com hemoglobina S de 38%, hemoglobina A de 59% e A2 normal, em adulto com hemograma normal, define traço falciforme (HbAS), condição benigna que não é anemia falciforme. Não há indicação de hidroxiureia (C), reservada à doença falciforme com crises ou complicações, nem de Doppler transcraniano (A), rastreamento de acidente vascular em crianças com HbSS entre 2 e 16 anos. A análise molecular dos genes da alfa-globina (D) explicaria por que a fração S é um pouco abaixo de 40%, mas não muda nenhuma conduta. O que o portador precisa é de aconselhamento genético: se a parceira também for portadora de traço ou de outra hemoglobinopatia, há 25% de chance de um filho com doença falciforme, e o casal deve ser orientado e testado.",
