      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Menino de 3 anos e 6 meses, previamente hígido, foi trazido pela mãe à UBS por febre de até 38o C e cansaço acima do habitual, quadro iniciado há cerca de 5 dias. Na noite anterior, relatou ter percebido manchas roxas em pernas e braços. Ao exame físico, a criança encontrava-se um pouco prostrada, com palidez cutaneomucosa, equimoses e petéquias nas faces interna e externa dos membros superiores e inferiores. O fígado era palpável 3 cm abaixo do rebordo costal direito. Demais aspectos do exame não revelaram particularidades. Considerando a principal hipótese diagnóstica, qual a conduta mais adequada?",
      "statement": "Menino de 3 anos e 6 meses, previamente hígido, foi trazido pela mãe à UBS por febre de até 38o C e cansaço acima do habitual, quadro iniciado há cerca de 5 dias. Na noite anterior, relatou ter percebido manchas roxas em pernas e braços. Ao exame físico, a criança encontrava-se um pouco prostrada, com palidez cutaneomucosa, equimoses e petéquias nas faces interna e externa dos membros superiores e inferiores. O fígado era palpável 3 cm abaixo do rebordo costal direito. Demais aspectos do exame não revelaram particularidades. Considerando a principal hipótese diagnóstica, qual a conduta mais adequada?",
