      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 63. Sem revisão clínica independente.",
      "officialComment": "Febre, cansaço, palidez, petéquias e equimoses em membros e hepatomegalia de 3 cm em pré-escolar previamente hígido combinam anemia, plaquetopenia e infiltração de órgãos: a hipótese principal é leucemia aguda, e o primeiro exame é o hemograma completo com contagem de plaquetas e diferencial, que orienta o mielograma. Encaminhar por maus-tratos (A) sem investigar seria um erro grave, ainda que a hipótese deva ser lembrada em equimoses de padrão atípico. Sorologias e coagulograma (B) e ultrassonografia com sangue oculto (C) podem vir depois, mas não respondem à suspeita central.",
      "explanation": "Febre, cansaço, palidez, petéquias e equimoses em membros e hepatomegalia de 3 cm em pré-escolar previamente hígido combinam anemia, plaquetopenia e infiltração de órgãos: a hipótese principal é leucemia aguda, e o primeiro exame é o hemograma completo com contagem de plaquetas e diferencial, que orienta o mielograma. Encaminhar por maus-tratos (A) sem investigar seria um erro grave, ainda que a hipótese deva ser lembrada em equimoses de padrão atípico. Sorologias e coagulograma (B) e ultrassonografia com sangue oculto (C) podem vir depois, mas não respondem à suspeita central.",
