      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 38. Sem revisão clínica independente.",
      "officialComment": "Linfonodo cervical de 2,5 cm, firme, indolor, não aderido, há mais de um mês, com calafrios recorrentes, prurido sem lesão de pele e edema facial matinal com turgência jugular, que sugere compressão da veia cava superior por massa mediastinal, é quadro de linfoma, provavelmente de Hodgkin, no qual o prurido é sintoma clássico. A conduta é biópsia excisional do linfonodo, que preserva a arquitetura para o diagnóstico histológico; a punção por agulha fina não basta. Antibiótico (A) trata linfadenite bacteriana, que seria dolorosa e aguda. Corticoide (B) pode mascarar e dificultar o diagnóstico de linfoma. A sorologia para mononucleose (D) cabe em jovem com faringite e linfonodos dolorosos, não neste quadro.",
      "explanation": "Linfonodo cervical de 2,5 cm, firme, indolor, não aderido, há mais de um mês, com calafrios recorrentes, prurido sem lesão de pele e edema facial matinal com turgência jugular, que sugere compressão da veia cava superior por massa mediastinal, é quadro de linfoma, provavelmente de Hodgkin, no qual o prurido é sintoma clássico. A conduta é biópsia excisional do linfonodo, que preserva a arquitetura para o diagnóstico histológico; a punção por agulha fina não basta. Antibiótico (A) trata linfadenite bacteriana, que seria dolorosa e aguda. Corticoide (B) pode mascarar e dificultar o diagnóstico de linfoma. A sorologia para mononucleose (D) cabe em jovem com faringite e linfonodos dolorosos, não neste quadro.",
