      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 61. Sem revisão clínica independente.",
      "officialComment": "Criança de 6 anos com picada de escorpião há 40 minutos, dor intensa, vômitos repetidos, sudorese, palidez, sialorreia, tremores e taquicardia tem escorpionismo moderado, com manifestações sistêmicas, e crianças são o grupo de maior risco de evolução para edema pulmonar e choque. A soroterapia antiescorpiônica é o tratamento específico e deve ser feita o mais cedo possível, na própria unidade que dispõe do soro, seguida de transferência para unidade hospitalar com capacidade de suporte intensivo. Transferir sem soro (B) ou apenas observar (A) perde tempo, e manter a criança na USF após o soro (D) é inadequado para um caso moderado em criança.",
      "explanation": "Criança de 6 anos com picada de escorpião há 40 minutos, dor intensa, vômitos repetidos, sudorese, palidez, sialorreia, tremores e taquicardia tem escorpionismo moderado, com manifestações sistêmicas, e crianças são o grupo de maior risco de evolução para edema pulmonar e choque. A soroterapia antiescorpiônica é o tratamento específico e deve ser feita o mais cedo possível, na própria unidade que dispõe do soro, seguida de transferência para unidade hospitalar com capacidade de suporte intensivo. Transferir sem soro (B) ou apenas observar (A) perde tempo, e manter a criança na USF após o soro (D) é inadequado para um caso moderado em criança.",
