      "text": "Homem de 30 anos, cacaueiro, do interior do Amazonas, com histórico de viagem recente aos Estados Unidos, inicia quadro súbito de febre alta de até 39oC, associado com mialgia, cefaleia, artralgia, dor retroorbitária e fotofobia há três dias. Há relato de epistaxe e algumas petéquias. Ele nega coriza, odinofagia e sintomas respiratórios. Ao exame físico, apresenta rash cutâneo em tronco e membros inferiores. O exame laboratorial revela leucócitos = 4.000/m3, com 40% de linfócitos, plaquetas = 98.000/mm3, velocidade de hemossedimentação (VHS) = 45mm/hora, creatinina = 1,0mg/dL, bilirrubina total = 1,8mg/dL e transaminases elevadas de forma discreta. Os testes de biologia molecular (PCR) para dengue, zika e chikungunya foram negativos. O diagnóstico mais provável é de febre por infecção:",
      "statement": "Homem de 30 anos, cacaueiro, do interior do Amazonas, com histórico de viagem recente aos Estados Unidos, inicia quadro súbito de febre alta de até 39oC, associado com mialgia, cefaleia, artralgia, dor retroorbitária e fotofobia há três dias. Há relato de epistaxe e algumas petéquias. Ele nega coriza, odinofagia e sintomas respiratórios. Ao exame físico, apresenta rash cutâneo em tronco e membros inferiores. O exame laboratorial revela leucócitos = 4.000/m3, com 40% de linfócitos, plaquetas = 98.000/mm3, velocidade de hemossedimentação (VHS) = 45mm/hora, creatinina = 1,0mg/dL, bilirrubina total = 1,8mg/dL e transaminases elevadas de forma discreta. Os testes de biologia molecular (PCR) para dengue, zika e chikungunya foram negativos. O diagnóstico mais provável é de febre por infecção:",
