      "officialComment": "Febre alta súbita com mialgia, cefaleia, artralgia, dor retro-orbitária, fotofobia, exantema, leucopenia e plaquetopenia leve, com PCR negativo para dengue, zika e chikungunya, em trabalhador de cacau do interior do Amazonas, é a apresentação típica da febre do Oropouche, arbovirose transmitida pelo maruim Culicoides paraensis e associada às plantações de cacau e banana, com epidemias recentes na região Norte. A leptospirose (A) cursa com mialgia de panturrilhas, sufusão conjuntival, icterícia rubínica e exposição a água contaminada. A febre amarela (B) evolui com icterícia, hemorragias e transaminases muito elevadas. Plasmodium ovale (C) é raro no Brasil e não causa exantema.",
      "explanation": "Febre alta súbita com mialgia, cefaleia, artralgia, dor retro-orbitária, fotofobia, exantema, leucopenia e plaquetopenia leve, com PCR negativo para dengue, zika e chikungunya, em trabalhador de cacau do interior do Amazonas, é a apresentação típica da febre do Oropouche, arbovirose transmitida pelo maruim Culicoides paraensis e associada às plantações de cacau e banana, com epidemias recentes na região Norte. A leptospirose (A) cursa com mialgia de panturrilhas, sufusão conjuntival, icterícia rubínica e exposição a água contaminada. A febre amarela (B) evolui com icterícia, hemorragias e transaminases muito elevadas. Plasmodium ovale (C) é raro no Brasil e não causa exantema.",
