      "text": "Paciente do sexo feminino, 72 anos, portadora de hipertensão arterial sistêmica, relata quadro de mialgia difusa associado à cefaleia, dor retrorbitária e a picos febris há 4 dias. Nega episódios de sangramentos espontâneos. Ao exame físico, prova do laço negativa. Considerando essas informações, a qual grupo da classificação de risco da dengue a paciente pertence e qual seria a conduta mais apropriada?",
      "statement": "Paciente do sexo feminino, 72 anos, portadora de hipertensão arterial sistêmica, relata quadro de mialgia difusa associado à cefaleia, dor retrorbitária e a picos febris há 4 dias. Nega episódios de sangramentos espontâneos. Ao exame físico, prova do laço negativa. Considerando essas informações, a qual grupo da classificação de risco da dengue a paciente pertence e qual seria a conduta mais apropriada?",
