      "officialComment": "Idosa de 72 anos, hipertensa, com síndrome febril de 4 dias compatível com dengue, sem sinais de alarme e com prova do laço negativa. Pela classificação do Ministério da Saúde, pacientes com comorbidade, idade acima de 65 anos ou risco social pertencem ao grupo B: hidratação oral, sintomáticos, hemograma e exame específico (NS1 ou sorologia conforme o dia), com a paciente em observação até o resultado; hematócrito elevado a reclassifica como grupo C. O grupo C (B) exige sinal de alarme, e a hidratação venosa (D) é conduta desse grupo. O grupo A (C) é reservado a quem não tem comorbidade nem fator de risco.",
