      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Um homem de 40 anos, sem comorbidades conhecidas, é internado em enfermaria de clínica médica para investigação de febre e perda de peso. Refere, há quatro meses, episódios recorrentes de febre vespertina, além de astenia e perda ponderal de 10kg. Ao exame, apresenta-se hipocorado e com baço palpável a 15cm do rebordo costal esquerdo. Exames laboratoriais evidenciam pancitopenia e hipoalbuminemia. É realizado aspirado de MO, que revela células ovoides com núcleo grande no interior dos macrófagos. O diagnóstico mais provável, nesse caso, é:",
      "statement": "Um homem de 40 anos, sem comorbidades conhecidas, é internado em enfermaria de clínica médica para investigação de febre e perda de peso. Refere, há quatro meses, episódios recorrentes de febre vespertina, além de astenia e perda ponderal de 10kg. Ao exame, apresenta-se hipocorado e com baço palpável a 15cm do rebordo costal esquerdo. Exames laboratoriais evidenciam pancitopenia e hipoalbuminemia. É realizado aspirado de MO, que revela células ovoides com núcleo grande no interior dos macrófagos. O diagnóstico mais provável, nesse caso, é:",
