      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 94. Sem revisão clínica independente.",
      "officialComment": "Febre vespertina há quatro meses, emagrecimento de 10 kg, esplenomegalia volumosa a 15 cm do rebordo, pancitopenia e hipoalbuminemia, com aspirado de medula mostrando células ovoides com núcleo grande no interior de macrófagos, descrevem as formas amastigotas de Leishmania: é leishmaniose visceral (calazar). A tricoleucemia (A) mostra linfócitos com projeções citoplasmáticas e fibrose medular. A doença de Gaucher (C) tem macrófagos com citoplasma em papel amassado, não microrganismos intracelulares. A amiloidose (B) se confirma pelo vermelho do Congo em biópsia de tecido. O tratamento é anfotericina B lipossomal.",
