      "edition": "tpi-2026-2-tpi2",
      "text": "Gestante, 28 anos, no segundo trimestre de gestação, procura atendimento médico relatando eliminação de segmentos semelhantes a \"fitas brancas\" nas fezes, acompanhada de dor abdominal leve e episódios de diarreia. Relata consumo recente de carne suína malcozida. O exame protoparasitológico confirma a presença de proglótides. Além de orientar medidas de higiene alimentar, qual é, respectivamente, o diagnóstico mais provável e a conduta mais adequada para o manejo inicial dessa paciente?",
      "statement": "Gestante, 28 anos, no segundo trimestre de gestação, procura atendimento médico relatando eliminação de segmentos semelhantes a \"fitas brancas\" nas fezes, acompanhada de dor abdominal leve e episódios de diarreia. Relata consumo recente de carne suína malcozida. O exame protoparasitológico confirma a presença de proglótides. Além de orientar medidas de higiene alimentar, qual é, respectivamente, o diagnóstico mais provável e a conduta mais adequada para o manejo inicial dessa paciente?",
