      "officialComment": "Eliminação de proglótides após consumo de carne suína malcozida é teníase por Taenia solium. O tratamento de escolha é o praziquantel em dose única de 5 a 10 mg/kg, permitido na gestação (categoria B); a niclosamida, não absorvida, é a alternativa igualmente segura. O albendazol (B e C) é evitado sobretudo no primeiro trimestre e não é o tratamento da teníase intestinal, embora seja usado na neurocisticercose. A ascaridíase (C e D) não elimina proglótides. Tratar a portadora também protege a família do risco de cisticercose por ingestão de ovos.",
      "explanation": "Eliminação de proglótides após consumo de carne suína malcozida é teníase por Taenia solium. O tratamento de escolha é o praziquantel em dose única de 5 a 10 mg/kg, permitido na gestação (categoria B); a niclosamida, não absorvida, é a alternativa igualmente segura. O albendazol (B e C) é evitado sobretudo no primeiro trimestre e não é o tratamento da teníase intestinal, embora seja usado na neurocisticercose. A ascaridíase (C e D) não elimina proglótides. Tratar a portadora também protege a família do risco de cisticercose por ingestão de ovos.",
