      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 16. Sem revisão clínica independente.",
      "officialComment": "Criança com febre, letargia, Glasgow 14, taquicardia de 140, pressão de 90 por 40 com pulsos amplos e enchimento capilar rápido tem sepse com choque quente. O contexto, alta há dois dias de terapia intensiva após ter cateter venoso central e sonda vesical, torna provável uma infecção associada a cuidados de saúde por germe resistente. A conduta na primeira hora é expandir com cristaloide (10 a 20 mL/kg, reavaliando) e iniciar antibiótico de espectro estendido, colhendo culturas sem atrasar a dose. Aguardar lactato e coagulograma (B) ou sedimento urinário (C) adia o tratamento e aumenta a mortalidade. Fluido de manutenção com cefalosporina de terceira geração (D) ignora o choque e o risco de resistência.",
      "explanation": "Criança com febre, letargia, Glasgow 14, taquicardia de 140, pressão de 90 por 40 com pulsos amplos e enchimento capilar rápido tem sepse com choque quente. O contexto, alta há dois dias de terapia intensiva após ter cateter venoso central e sonda vesical, torna provável uma infecção associada a cuidados de saúde por germe resistente. A conduta na primeira hora é expandir com cristaloide (10 a 20 mL/kg, reavaliando) e iniciar antibiótico de espectro estendido, colhendo culturas sem atrasar a dose. Aguardar lactato e coagulograma (B) ou sedimento urinário (C) adia o tratamento e aumenta a mortalidade. Fluido de manutenção com cefalosporina de terceira geração (D) ignora o choque e o risco de resistência.",
      "sourceCommentImported": true,
      "commentStatus": "source-imported",
      "commentTopic": "Clínica Médica › Infectologia › Sepse e choque séptico",
