      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Um homem de 24 anos, com diagnóstico de HIV, em uso irregular de tenofovir, lamivudina e efavirenz e com CD4 = 60 células/mm3, comparece ao ambulatório de clínica médica queixando-se de tosse seca e perda de peso há dois meses. Foram solicitados radiografia de tórax, que não revelou alterações, e BAAR do escarro induzido, que foi negativo. O PPD teve resultado de 8mm, e a pesquisa de antígeno urinário para tuberculose foi positiva. A conduta mais apropriada no momento é:",
      "statement": "Um homem de 24 anos, com diagnóstico de HIV, em uso irregular de tenofovir, lamivudina e efavirenz e com CD4 = 60 células/mm3, comparece ao ambulatório de clínica médica queixando-se de tosse seca e perda de peso há dois meses. Foram solicitados radiografia de tórax, que não revelou alterações, e BAAR do escarro induzido, que foi negativo. O PPD teve resultado de 8mm, e a pesquisa de antígeno urinário para tuberculose foi positiva. A conduta mais apropriada no momento é:",
