      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 13. Sem revisão clínica independente.",
      "officialComment": "Pessoa vivendo com HIV com CD4 de 60 células, tosse e emagrecimento há dois meses tem alta probabilidade de tuberculose mesmo com radiografia normal e baciloscopia negativa, porque a imunossupressão avançada produz formas atípicas e paucibacilares. Nesse cenário, o teste de antígeno urinário (LF-LAM) positivo tem valor diagnóstico e autoriza iniciar o tratamento da doença ativa: rifampicina, isoniazida, pirazinamida e etambutol por dois meses, seguidos de rifampicina e isoniazida por quatro. Isoniazida isolada (B e D) e rifapentina com isoniazida (C) tratam infecção latente e são contraindicadas sem excluir doença ativa; dolutegravir e levofloxacino não compõem esquema de tuberculose. A terapia antirretroviral deve ser otimizada, lembrando que a rifampicina exige dose dobrada de dolutegravir.",
      "explanation": "Pessoa vivendo com HIV com CD4 de 60 células, tosse e emagrecimento há dois meses tem alta probabilidade de tuberculose mesmo com radiografia normal e baciloscopia negativa, porque a imunossupressão avançada produz formas atípicas e paucibacilares. Nesse cenário, o teste de antígeno urinário (LF-LAM) positivo tem valor diagnóstico e autoriza iniciar o tratamento da doença ativa: rifampicina, isoniazida, pirazinamida e etambutol por dois meses, seguidos de rifampicina e isoniazida por quatro. Isoniazida isolada (B e D) e rifapentina com isoniazida (C) tratam infecção latente e são contraindicadas sem excluir doença ativa; dolutegravir e levofloxacino não compõem esquema de tuberculose. A terapia antirretroviral deve ser otimizada, lembrando que a rifampicina exige dose dobrada de dolutegravir.",
