      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Uma mulher de 40 anos, sem comorbidades conhecidas, é internada na enfermaria de clínica médica para investigação de síndrome edemigênica. Ela relata início do quadro há três meses, com edema de membros inferiores e aumento do volume abdominal de evolução progressiva; nega dispneia, oligúria ou alterações de coloração da urina. Os exames laboratoriais evidenciam creatinina = 0,9mg/dL, albumina = 1,8g/dL e triglicerídeos = 320mg/dL. O sedimento urinário demonstra proteinúria 4+/4+, sem outras alterações. Considerando o diagnóstico mais provável, dois exames que devem ser solicitados na investigação etiológica desse caso são:",
      "statement": "Uma mulher de 40 anos, sem comorbidades conhecidas, é internada na enfermaria de clínica médica para investigação de síndrome edemigênica. Ela relata início do quadro há três meses, com edema de membros inferiores e aumento do volume abdominal de evolução progressiva; nega dispneia, oligúria ou alterações de coloração da urina. Os exames laboratoriais evidenciam creatinina = 0,9mg/dL, albumina = 1,8g/dL e triglicerídeos = 320mg/dL. O sedimento urinário demonstra proteinúria 4+/4+, sem outras alterações. Considerando o diagnóstico mais provável, dois exames que devem ser solicitados na investigação etiológica desse caso são:",
