      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 51. Sem revisão clínica independente.",
      "officialComment": "Edema progressivo, albumina de 1,8 g/dL, proteinúria maciça e hipertrigliceridemia com sedimento sem hematúria definem síndrome nefrótica em adulta. As causas mais frequentes são nefropatia membranosa, glomeruloesclerose segmentar e focal e lesões mínimas. A membranosa, a mais comum nessa faixa, pode ser primária, marcada pelo anticorpo antifosfolipase A2, ou secundária a hepatite B, lúpus e neoplasias; por isso sorologia para hepatite B e anti-PLA2R fazem parte da investigação inicial. Antiestreptolisina O (A) e anticorpo antimembrana basal (D) pertencem a síndromes nefríticas. Hepatite C com crioglobulinas (C) causa glomerulonefrite membranoproliferativa, de padrão nefrítico-nefrótico com hematúria.",
      "explanation": "Edema progressivo, albumina de 1,8 g/dL, proteinúria maciça e hipertrigliceridemia com sedimento sem hematúria definem síndrome nefrótica em adulta. As causas mais frequentes são nefropatia membranosa, glomeruloesclerose segmentar e focal e lesões mínimas. A membranosa, a mais comum nessa faixa, pode ser primária, marcada pelo anticorpo antifosfolipase A2, ou secundária a hepatite B, lúpus e neoplasias; por isso sorologia para hepatite B e anti-PLA2R fazem parte da investigação inicial. Antiestreptolisina O (A) e anticorpo antimembrana basal (D) pertencem a síndromes nefríticas. Hepatite C com crioglobulinas (C) causa glomerulonefrite membranoproliferativa, de padrão nefrítico-nefrótico com hematúria.",
      "sourceCommentImported": true,
      "commentStatus": "source-imported",
      "commentTopic": "Clínica Médica › Nefrologia › Síndrome nefrótica",
      "source": "TPI 2026.2 - TPI 2",
