      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 45. Sem revisão clínica independente.",
      "officialComment": "Menino de 7 anos com crises breves durante o sono, sialorreia, alteração da fala e parestesia de língua, lábios e bochecha, exame normal e eletroencefalograma com ondas agudas bifásicas centrotemporais ativadas pelo sono tem epilepsia rolândica (epilepsia focal autolimitada com pontas centrotemporais), a epilepsia focal mais comum da infância, de prognóstico excelente e remissão na adolescência. A síndrome de Landau-Kleffner (B) é afasia adquirida com ponta-onda contínua no sono. O terror noturno (D) não tem sintomas focais nem alteração do EEG. Isquemia transitória (A) é excepcional nessa idade e não se repetiria com esse padrão.",
      "explanation": "Menino de 7 anos com crises breves durante o sono, sialorreia, alteração da fala e parestesia de língua, lábios e bochecha, exame normal e eletroencefalograma com ondas agudas bifásicas centrotemporais ativadas pelo sono tem epilepsia rolândica (epilepsia focal autolimitada com pontas centrotemporais), a epilepsia focal mais comum da infância, de prognóstico excelente e remissão na adolescência. A síndrome de Landau-Kleffner (B) é afasia adquirida com ponta-onda contínua no sono. O terror noturno (D) não tem sintomas focais nem alteração do EEG. Isquemia transitória (A) é excepcional nessa idade e não se repetiria com esse padrão.",
