      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Homem de 75 anos de idade retorna ao ambulatório por quadro de tosse há cerca de 3 semanas, com melhora parcial nos últimos dias. É hipertenso e tabagista de 60 anos- maço. A tomografia de tórax revela nódulo periférico, sólido, de 1,2 cm de diâmetro, em lobo superior direito. Não mostra outras alterações. O paciente nega emagrecimento, febre, dor torácica ou hemoptise. Queixase apenas de tosse, que diz que até já melhorou um pouco. A melhor conduta para este paciente, dentre as abaixo, é:",
      "statement": "Homem de 75 anos de idade retorna ao ambulatório por quadro de tosse há cerca de 3 semanas, com melhora parcial nos últimos dias. É hipertenso e tabagista de 60 anos- maço. A tomografia de tórax revela nódulo periférico, sólido, de 1,2 cm de diâmetro, em lobo superior direito. Não mostra outras alterações. O paciente nega emagrecimento, febre, dor torácica ou hemoptise. Queixase apenas de tosse, que diz que até já melhorou um pouco. A melhor conduta para este paciente, dentre as abaixo, é:",
