      "officialComment": "Nódulo pulmonar sólido de 1,2 cm, em lobo superior, em homem de 75 anos com carga tabágica de 60 anos-maço, tem probabilidade pré-teste de malignidade alta, acima de 65%. Para nódulos de alta probabilidade a conduta é obter diagnóstico histológico ou ressecar; a biópsia percutânea guiada por tomografia é o método de escolha para lesão periférica e tem menor morbidade do que a toracoscopia (C) num idoso. O seguimento tomográfico (B) é para nódulos pequenos e de baixa probabilidade. A broncoscopia (D) tem baixo rendimento em nódulos periféricos pequenos.",
      "explanation": "Nódulo pulmonar sólido de 1,2 cm, em lobo superior, em homem de 75 anos com carga tabágica de 60 anos-maço, tem probabilidade pré-teste de malignidade alta, acima de 65%. Para nódulos de alta probabilidade a conduta é obter diagnóstico histológico ou ressecar; a biópsia percutânea guiada por tomografia é o método de escolha para lesão periférica e tem menor morbidade do que a toracoscopia (C) num idoso. O seguimento tomográfico (B) é para nódulos pequenos e de baixa probabilidade. A broncoscopia (D) tem baixo rendimento em nódulos periféricos pequenos.",
