      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 71. Sem revisão clínica independente.",
      "officialComment": "O líquido pleural tem relação proteína pleural/sérica de 0,33, relação LDH de 0,36 e LDH abaixo de dois terços do limite normal: pelos critérios de Light é um transudato. Isso afasta as causas exsudativas típicas, como tuberculose pleural (D), que é exsudato linfocítico com ADA elevada, e lúpus (B). A insuficiência cardíaca (C), causa clássica de transudato, não se sustenta em jovem sem ortopneia, sem edema, com área cardíaca normal e sem derrame pericárdico. O que explica sudorese noturna, febre, emagrecimento e linfonodomegalias mediastinais é o linfoma: a massa mediastinal obstrui a drenagem linfática e venosa e produz derrame de baixa proteína. A confirmação vem da biópsia dos linfonodos.",
      "explanation": "O líquido pleural tem relação proteína pleural/sérica de 0,33, relação LDH de 0,36 e LDH abaixo de dois terços do limite normal: pelos critérios de Light é um transudato. Isso afasta as causas exsudativas típicas, como tuberculose pleural (D), que é exsudato linfocítico com ADA elevada, e lúpus (B). A insuficiência cardíaca (C), causa clássica de transudato, não se sustenta em jovem sem ortopneia, sem edema, com área cardíaca normal e sem derrame pericárdico. O que explica sudorese noturna, febre, emagrecimento e linfonodomegalias mediastinais é o linfoma: a massa mediastinal obstrui a drenagem linfática e venosa e produz derrame de baixa proteína. A confirmação vem da biópsia dos linfonodos.",
