      "edition": "tpi-2026-2-tpi2",
      "text": "Um idoso de 82 anos, engenheiro aposentado, comparece à atenção primária à saúde (APS) por queixa de esquecimento. A filha refere que o quadro se iniciou há seis meses, com lapsos de memória e redução da capacidade de realização das atividades de vida diária. Ele relata o falecimento da esposa um mês antes dos sintomas. Ao exame neurológico, o paciente está desperto, orientado, mas demonstra apatia e abulia. Apresenta leve tremor de intenção simétrico nas mãos, com melhora em repouso, sendo o restante do exame normal. O miniexame do estado mental tem resultado de 26 pontos. O diagnóstico mais provável é:",
      "statement": "Um idoso de 82 anos, engenheiro aposentado, comparece à atenção primária à saúde (APS) por queixa de esquecimento. A filha refere que o quadro se iniciou há seis meses, com lapsos de memória e redução da capacidade de realização das atividades de vida diária. Ele relata o falecimento da esposa um mês antes dos sintomas. Ao exame neurológico, o paciente está desperto, orientado, mas demonstra apatia e abulia. Apresenta leve tremor de intenção simétrico nas mãos, com melhora em repouso, sendo o restante do exame normal. O miniexame do estado mental tem resultado de 26 pontos. O diagnóstico mais provável é:",
