      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 97. Sem revisão clínica independente.",
      "officialComment": "Idoso de 82 anos com esquecimento e redução das atividades diárias iniciados um mês após a morte da esposa, apatia e abulia ao exame, miniexame do estado mental de 26 pontos, normal para a escolaridade, e exame neurológico normal exceto tremor de intenção leve. O início identificável após uma perda, o predomínio de apatia e o desempenho preservado no rastreio cognitivo apontam para depressão maior no idoso, a chamada pseudodemência depressiva. A doença de Alzheimer (C) é insidiosa, com rastreio alterado e pouca crítica do déficit. A demência por corpúsculos de Lewy (A) exige alucinações visuais, flutuação e parkinsonismo. A demência vascular (D) tem evolução em degraus e sinais focais. Tratar a depressão e reavaliar a cognição é a conduta.",
      "explanation": "Idoso de 82 anos com esquecimento e redução das atividades diárias iniciados um mês após a morte da esposa, apatia e abulia ao exame, miniexame do estado mental de 26 pontos, normal para a escolaridade, e exame neurológico normal exceto tremor de intenção leve. O início identificável após uma perda, o predomínio de apatia e o desempenho preservado no rastreio cognitivo apontam para depressão maior no idoso, a chamada pseudodemência depressiva. A doença de Alzheimer (C) é insidiosa, com rastreio alterado e pouca crítica do déficit. A demência por corpúsculos de Lewy (A) exige alucinações visuais, flutuação e parkinsonismo. A demência vascular (D) tem evolução em degraus e sinais focais. Tratar a depressão e reavaliar a cognição é a conduta.",
