      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Paciente masculino, 32 anos, é levado ao setor de emergência. com agitação psicomotora importante, queixando-se de cefaleia e evoluindo com sudorese. Ao exame físico, encontra-se acordado, agitado, taquicárdico (FC= 130 bpm) hipertenso (PA = 190 X 100 mmHg), e taquipneico (FR:24 mrm). Além disso, observa-se midríase ao exame físico. Glicemia e eletrocardiograma foram normais. Há relato de uso de cocaína e opioides. Encontra-se com saturação de oxigênio normal e não tem indicação para suporte ventilatório mecânico. Qual das medicações abaixo estaria mais indicada para o manejo do quadro clínico acima descrito?",
      "statement": "Paciente masculino, 32 anos, é levado ao setor de emergência. com agitação psicomotora importante, queixando-se de cefaleia e evoluindo com sudorese. Ao exame físico, encontra-se acordado, agitado, taquicárdico (FC= 130 bpm) hipertenso (PA = 190 X 100 mmHg), e taquipneico (FR:24 mrm). Além disso, observa-se midríase ao exame físico. Glicemia e eletrocardiograma foram normais. Há relato de uso de cocaína e opioides. Encontra-se com saturação de oxigênio normal e não tem indicação para suporte ventilatório mecânico. Qual das medicações abaixo estaria mais indicada para o manejo do quadro clínico acima descrito?",
      "opts": [
        "Haloperidol.",
        "Flumazenil.",
        "Naloxone.",
        "Diazepam."
      ],
