      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 81. Sem revisão clínica independente.",
      "officialComment": "Agitação, cefaleia, sudorese, taquicardia, hipertensão, taquipneia e midríase após uso de cocaína configuram síndrome simpaticomimética. A base do tratamento é o benzodiazepínico intravenoso, aqui o diazepam, que controla a agitação, reduz a pressão e a frequência cardíaca e previne convulsões e isquemia miocárdica. O haloperidol (A) baixa o limiar convulsivo e piora a hipertermia. A naloxona (C) trata intoxicação por opioide, que se apresenta com miose e depressão respiratória, ausentes, e poderia desmascarar ainda mais o efeito da cocaína. O flumazenil (B) é antídoto de benzodiazepínico. Betabloqueadores são contraindicados pelo risco de vasoconstrição alfa sem oposição.",
      "explanation": "Agitação, cefaleia, sudorese, taquicardia, hipertensão, taquipneia e midríase após uso de cocaína configuram síndrome simpaticomimética. A base do tratamento é o benzodiazepínico intravenoso, aqui o diazepam, que controla a agitação, reduz a pressão e a frequência cardíaca e previne convulsões e isquemia miocárdica. O haloperidol (A) baixa o limiar convulsivo e piora a hipertermia. A naloxona (C) trata intoxicação por opioide, que se apresenta com miose e depressão respiratória, ausentes, e poderia desmascarar ainda mais o efeito da cocaína. O flumazenil (B) é antídoto de benzodiazepínico. Betabloqueadores são contraindicados pelo risco de vasoconstrição alfa sem oposição.",
