      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 83. Sem revisão clínica independente.",
      "officialComment": "Galactorreia, aumento das mamas, oligomenorreia e perda de libido com prolactina elevada em paciente que usa antipsicótico: entre os fármacos listados, a risperidona é o que mais eleva a prolactina, porque bloqueia intensamente os receptores D2 da via tuberoinfundibular e atravessa pouco a barreira hematoencefálica, mantendo bloqueio periférico prolongado; paliperidona, haloperidol e amissulprida têm o mesmo perfil. Quetiapina (A) e olanzapina (B) poupam a prolactina, e o aripiprazol pode até reduzi-la. A clorpromazina (C) eleva a prolactina, mas bem menos que a risperidona. A conduta é reduzir a dose ou trocar por aripiprazol.",
      "explanation": "Galactorreia, aumento das mamas, oligomenorreia e perda de libido com prolactina elevada em paciente que usa antipsicótico: entre os fármacos listados, a risperidona é o que mais eleva a prolactina, porque bloqueia intensamente os receptores D2 da via tuberoinfundibular e atravessa pouco a barreira hematoencefálica, mantendo bloqueio periférico prolongado; paliperidona, haloperidol e amissulprida têm o mesmo perfil. Quetiapina (A) e olanzapina (B) poupam a prolactina, e o aripiprazol pode até reduzi-la. A clorpromazina (C) eleva a prolactina, mas bem menos que a risperidona. A conduta é reduzir a dose ou trocar por aripiprazol.",
