      "text": "Criança, 6 anos de idade, é levada ao pronto atendimento com história de dor abdominal difusa há 10 dias, artralgia em joelhos e exantema purpúrico palpável em membros inferiores. Ao exame físico, apresenta lesões purpúricas simétricas em região glútea e pernas. Realizado hemograma completo sem alterações. De acordo com o relato do caso clínico, qual é o diagnóstico mais provável e a principal complicação a longo prazo associada a essa condição?",
      "statement": "Criança, 6 anos de idade, é levada ao pronto atendimento com história de dor abdominal difusa há 10 dias, artralgia em joelhos e exantema purpúrico palpável em membros inferiores. Ao exame físico, apresenta lesões purpúricas simétricas em região glútea e pernas. Realizado hemograma completo sem alterações. De acordo com o relato do caso clínico, qual é o diagnóstico mais provável e a principal complicação a longo prazo associada a essa condição?",
