      "officialComment": "Púrpura palpável simétrica em membros inferiores e glúteos, artralgia e dor abdominal em criança de 6 anos com plaquetas normais é o quadro clássico da vasculite por IgA (púrpura de Henoch-Schönlein), a vasculite mais comum da infância. A plaqueta normal afasta a púrpura trombocitopênica (C). A doença de Kawasaki (A) exige febre por cinco dias com conjuntivite, alterações orais e de extremidades. O lúpus juvenil (B) cursa com outros critérios e autoanticorpos. A complicação que define o prognóstico a longo prazo é a nefrite por IgA, que aparece em semanas a meses com hematúria e proteinúria; por isso a criança deve ter exame de urina e pressão arterial monitorados por pelo menos seis a doze meses após o episódio.",
      "explanation": "Púrpura palpável simétrica em membros inferiores e glúteos, artralgia e dor abdominal em criança de 6 anos com plaquetas normais é o quadro clássico da vasculite por IgA (púrpura de Henoch-Schönlein), a vasculite mais comum da infância. A plaqueta normal afasta a púrpura trombocitopênica (C). A doença de Kawasaki (A) exige febre por cinco dias com conjuntivite, alterações orais e de extremidades. O lúpus juvenil (B) cursa com outros critérios e autoanticorpos. A complicação que define o prognóstico a longo prazo é a nefrite por IgA, que aparece em semanas a meses com hematúria e proteinúria; por isso a criança deve ter exame de urina e pressão arterial monitorados por pelo menos seis a doze meses após o episódio.",
