      "text": "Menina de 6 anos apresenta, há 2 dias, dor abdominal, inicialmente difusa e, agora, está mais localizada em fossa ilíaca direita. Está com apetite diminuído, com náuseas e vômitos. Há 1 dia, apresenta dor para urinar e um episódio de febre (37,8 oC). Possui hábito intestinal regular, diário, sem esforço, mas está há 1 dia sem evacuar. Exame físico: prostrada, FC: 102 bpm, discretamente desidratada. Abdome: doloroso à palpação profunda difusamente, com sinal de Blumberg positivo. Em face do exposto, a conduta a ser adotada é realizar",
