      "officialComment": "Dor abdominal que começa difusa e se localiza na fossa ilíaca direita, com anorexia, náuseas, vômitos, febre baixa e sinal de Blumberg, é apendicite aguda até prova em contrário; a disúria sugere apêndice pélvico irritando a bexiga. Em criança com quadro clínico típico e sinal de irritação peritoneal, a conduta é apendicectomia de urgência, sem retardar pelo exame de imagem; se houvesse dúvida, a ultrassonografia seria o exame de escolha, evitando a radiação da tomografia (D). Observar por 48 horas (B) aumenta o risco de perfuração. A drenagem guiada (C) é conduta para abscesso periapendicular tardio, não para o quadro inicial.",
      "explanation": "Dor abdominal que começa difusa e se localiza na fossa ilíaca direita, com anorexia, náuseas, vômitos, febre baixa e sinal de Blumberg, é apendicite aguda até prova em contrário; a disúria sugere apêndice pélvico irritando a bexiga. Em criança com quadro clínico típico e sinal de irritação peritoneal, a conduta é apendicectomia de urgência, sem retardar pelo exame de imagem; se houvesse dúvida, a ultrassonografia seria o exame de escolha, evitando a radiação da tomografia (D). Observar por 48 horas (B) aumenta o risco de perfuração. A drenagem guiada (C) é conduta para abscesso periapendicular tardio, não para o quadro inicial.",
