      "officialComment": "Idosa no pós-operatório de cirurgia cardíaca, com distensão abdominal progressiva, parada de eliminação de gases, hipocalemia, uso de analgesia e tomografia com dilatação difusa do cólon, sobretudo ceco e ascendente, sem ponto de transição e sem sinais de sofrimento, tem pseudo-obstrução colônica aguda, a síndrome de Ogilvie. A obstrução por bridas (A) mostraria alças de delgado dilatadas com ponto de transição, e o cólon colapsado. A isquemia mesentérica (C) cursa com dor desproporcional ao exame, acidose e pneumatose. A gastroparesia (D) não distende o cólon. A conduta é jejum, sonda nasogástrica, correção do potássio, suspensão de opioides e, se o ceco passar de 10 a 12 cm, neostigmina ou descompressão colonoscópica.",
