      "text": "Homem, 58 anos, relata dor abdominal difusa iniciada há 24 horas, de intensidade moderada a forte, associada a náuseas e vômitos alimentares que evoluíram para biliosos. Refere parada de eliminação de gases há 12 horas e de fezes há 24 horas. Antecedentes cirúrgicos de laparotomia exploradora por trauma abdominal há 8 anos e apendicectomia há 20 anos. Ao exame físico, apresenta regular estado geral, FC 110 bpm, PA 110/70 mmHg e temperatura axilar de 37,7 °C. Abdome moderadamente distendido, com dor à palpação difusa, mais intensa em região periumbilical, sem sinais de irritação peritoneal. Ruídos hidroaéreos presentes, pouco aumentados. A TC de abdome com contraste endovenoso demonstra segmento de jejuno distal dilatado entre dois pontos de estreitamento, com espessura da parede de 4 mm e redução do realce parietal pelo contraste, pequena quantidade de líquido entre alças, dilatação do intestino delgado proximal e estômago, e ausência de pneumoperitônio. Considerando o quadro apresentado, qual é a conduta terapêutica mais indicada?",
      "statement": "Homem, 58 anos, relata dor abdominal difusa iniciada há 24 horas, de intensidade moderada a forte, associada a náuseas e vômitos alimentares que evoluíram para biliosos. Refere parada de eliminação de gases há 12 horas e de fezes há 24 horas. Antecedentes cirúrgicos de laparotomia exploradora por trauma abdominal há 8 anos e apendicectomia há 20 anos. Ao exame físico, apresenta regular estado geral, FC 110 bpm, PA 110/70 mmHg e temperatura axilar de 37,7 °C. Abdome moderadamente distendido, com dor à palpação difusa, mais intensa em região periumbilical, sem sinais de irritação peritoneal. Ruídos hidroaéreos presentes, pouco aumentados. A TC de abdome com contraste endovenoso demonstra segmento de jejuno distal dilatado entre dois pontos de estreitamento, com espessura da parede de 4 mm e redução do realce parietal pelo contraste, pequena quantidade de líquido entre alças, dilatação do intestino delgado proximal e estômago, e ausência de pneumoperitônio. Considerando o quadro apresentado, qual é a conduta terapêutica mais indicada?",
