      "officialComment": "Obstrução de delgado em paciente com duas laparotomias prévias tem as bridas como causa mais provável, mas a tomografia mostra sinais de sofrimento de alça: segmento dilatado entre dois pontos de estreitamento (alça fechada), redução do realce parietal e líquido entre as alças, com taquicardia e febrícula. Alça fechada com hipoperfusão evolui para estrangulamento e necrose, e a conduta é cirurgia imediata. O tratamento conservador com sonda e hidratação (D) só é aceitável em obstrução parcial sem sinais de isquemia. Trânsito contrastado (A) e dosagem de lactato (C) atrasam a decisão já definida pela imagem.",
