      "officialComment": "Pirose e epigastralgia típicas há 2 anos, sem disfagia ou emagrecimento, com três endoscopias sem esofagite e sem resposta ao omeprazol, configuram doença do refluxo não erosiva refratária, que precisa ser diferenciada da pirose funcional. O exame que quantifica a exposição ácida e correlaciona os sintomas com os episódios de refluxo é a pHmetria (ou impedanciopHmetria) esofágica, feita fora do inibidor de bomba. A manometria de alta resolução (B) exclui acalasia e é pré-operatória, mas não diagnostica refluxo. A esofagite eosinofílica (C) se manifesta por disfagia e impactação alimentar, ausentes. A acalasia (A) cursa com disfagia e regurgitação.",
