      "edition": "tpi-2026-2-tpi2",
      "text": "Paciente de 70 anos, do sexo feminino, comparece a consulta trazendo exame de tomografia computadorizada de abdome, feita no Pronto Atendimento devido a quadro de lombalgia, evidenciando nódulo hipervascular no colo do pâncreas de 1,9cm de diâmetro. Nega outros sintomas e diz estar sentindo- se muito bem, porém está muito apreensiva devido ao resultado do exame pela possibilidade de ser um câncer de pâncreas. Dentre as opções abaixo, em relação à conduta frente esta situação, assinale a alternativa CORRETA:",
      "statement": "Paciente de 70 anos, do sexo feminino, comparece a consulta trazendo exame de tomografia computadorizada de abdome, feita no Pronto Atendimento devido a quadro de lombalgia, evidenciando nódulo hipervascular no colo do pâncreas de 1,9cm de diâmetro. Nega outros sintomas e diz estar sentindo- se muito bem, porém está muito apreensiva devido ao resultado do exame pela possibilidade de ser um câncer de pâncreas. Dentre as opções abaixo, em relação à conduta frente esta situação, assinale a alternativa CORRETA:",
