      "officialComment": "Nódulo pancreático sólido, hipervascular na fase arterial, de 1,9 cm, em idosa assintomática, tem como principal hipótese o tumor neuroendócrino não funcionante; metástase de carcinoma renal e cistoadenoma seroso entram no diferencial. A conduta é confirmar o diagnóstico por ecoendoscopia com punção antes de decidir: tumores neuroendócrinos de 2 cm ou mais, ou com atipias, são ressecados; os menores e de baixo grau podem ser vigiados. Indicar pancreatectomia central (B) ou enucleação (C) sem diagnóstico histológico é precipitado, e acompanhar sem esclarecer (A) deixa sem resposta uma paciente apreensiva com lesão potencialmente maligna.",
      "explanation": "Nódulo pancreático sólido, hipervascular na fase arterial, de 1,9 cm, em idosa assintomática, tem como principal hipótese o tumor neuroendócrino não funcionante; metástase de carcinoma renal e cistoadenoma seroso entram no diferencial. A conduta é confirmar o diagnóstico por ecoendoscopia com punção antes de decidir: tumores neuroendócrinos de 2 cm ou mais, ou com atipias, são ressecados; os menores e de baixo grau podem ser vigiados. Indicar pancreatectomia central (B) ou enucleação (C) sem diagnóstico histológico é precipitado, e acompanhar sem esclarecer (A) deixa sem resposta uma paciente apreensiva com lesão potencialmente maligna.",
