      "text": "Paciente com 6 semanas de vida foi trazido à UBS por vômitos não biliosos, gradualmente crescentes, que progrediam para vômitos em jato, logo após ou durante a alimentação. A criança continuava com fome e não apresentava dor ou distensão abdominais. Ao exame, encontrava-se hidratada e em bom estado geral. Constatou-se pequena nodulação de cerca de 1 cm de diâmetro, palpável no quadrante superior direito do abdômen. Por vezes, era possível visualizar uma onda peristáltica que se movia do quadrante superior esquerdo para o direito. Qual a hipótese diagnóstica mais provável?",
      "statement": "Paciente com 6 semanas de vida foi trazido à UBS por vômitos não biliosos, gradualmente crescentes, que progrediam para vômitos em jato, logo após ou durante a alimentação. A criança continuava com fome e não apresentava dor ou distensão abdominais. Ao exame, encontrava-se hidratada e em bom estado geral. Constatou-se pequena nodulação de cerca de 1 cm de diâmetro, palpável no quadrante superior direito do abdômen. Por vezes, era possível visualizar uma onda peristáltica que se movia do quadrante superior esquerdo para o direito. Qual a hipótese diagnóstica mais provável?",
