      "officialComment": "Lactente de 6 semanas com vômitos não biliosos em jato logo após as mamadas, fome preservada, oliva pilórica palpável no quadrante superior direito e ondas peristálticas visíveis da esquerda para a direita tem estenose hipertrófica do piloro. A ultrassonografia confirma (espessura muscular acima de 3 a 4 mm e comprimento acima de 15 mm), a alcalose metabólica hipoclorêmica e hipocalêmica é corrigida antes da piloromiotomia de Fredet-Ramstedt. O refluxo (A) causa regurgitação, não vômito em jato com massa palpável. Má rotação com volvo (C) dá vômitos biliosos e é emergência. A intussuscepção (D) ocorre entre 6 e 36 meses, com dor paroxística e fezes em geleia de framboesa.",
      "explanation": "Lactente de 6 semanas com vômitos não biliosos em jato logo após as mamadas, fome preservada, oliva pilórica palpável no quadrante superior direito e ondas peristálticas visíveis da esquerda para a direita tem estenose hipertrófica do piloro. A ultrassonografia confirma (espessura muscular acima de 3 a 4 mm e comprimento acima de 15 mm), a alcalose metabólica hipoclorêmica e hipocalêmica é corrigida antes da piloromiotomia de Fredet-Ramstedt. O refluxo (A) causa regurgitação, não vômito em jato com massa palpável. Má rotação com volvo (C) dá vômitos biliosos e é emergência. A intussuscepção (D) ocorre entre 6 e 36 meses, com dor paroxística e fezes em geleia de framboesa.",
