      "text": "Homem, 28 anos, vítima de ferimento por arma de fogo em coxa direita, dá entrada no pronto-socorro com sangramento ativo moderado no local da lesão. Ao exame físico inicial, apresenta-se consciente, PA: 100x70 mmHg, FC: 110 bpm, com ausência de pulso pedioso e tibial posterior direitos. O pulso femoral direito está presente, mas diminuído em relação ao contralateral. Há hematoma expansivo em região inguinal direita e déficit sensitivo motor discreto do pé direito. A angiotomografia com contraste demonstra lesão da artéria femoral superficial direita com extravasamento ativo de contraste e hematoma adjacente. Qual a conduta mais adequada?",
