      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 10. Sem revisão clínica independente.",
      "officialComment": "O paciente tem sinais duros de lesão arterial: sangramento ativo, hematoma expansivo, ausência de pulsos distais e déficit neurológico do pé, e a angiotomografia confirma lesão da femoral superficial com extravasamento. Diante de sinais duros, a conduta é ex-ploração cirúrgica imediata com controle proximal e distal e reparo direto (sutura, anastomose ou interposição de veia safena), com fasciotomia se a isquemia for prolongada. O stent revestido (A) é opção em lesões selecionadas de pacientes estáveis, sem hematoma expansivo. A embolização (D) ocluiria a artéria principal do membro e causaria isquemia. Compressão e observação (B) permitiriam sangramento e perda do membro.",
      "explanation": "O paciente tem sinais duros de lesão arterial: sangramento ativo, hematoma expansivo, ausência de pulsos distais e déficit neurológico do pé, e a angiotomografia confirma lesão da femoral superficial com extravasamento. Diante de sinais duros, a conduta é ex-ploração cirúrgica imediata com controle proximal e distal e reparo direto (sutura, anastomose ou interposição de veia safena), com fasciotomia se a isquemia for prolongada. O stent revestido (A) é opção em lesões selecionadas de pacientes estáveis, sem hematoma expansivo. A embolização (D) ocluiria a artéria principal do membro e causaria isquemia. Compressão e observação (B) permitiriam sangramento e perda do membro.",
      "sourceCommentImported": true,
