      "answer": "A",
      "correctAnswer": "A",
      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 29. Sem revisão clínica independente.",
      "officialComment": "Dor inguinal insidiosa e progressiva há 4 anos, limitação para calçar meias e sapatos (perda de flexão e rotação do quadril), dor noturna e em repouso, e radiografia com redução do espaço articular, esclerose subcondral e osteófitos são o quadro completo da osteoartrite do quadril. Após mais de seis meses de fisioterapia, anti-inflamatórios e opioides sem controle, a artroplastia total do quadril é o tratamento de escolha, com excelente alívio da dor. A osteonecrose (B) tem radiografia inicial normal ou com sinal do crescente e a artroplastia parcial se reserva a fraturas do colo em idosos frágeis. Não há fratura (C) nem os achados da osteoporose (D), que é radiograficamente silenciosa até fraturar.",
      "explanation": "Dor inguinal insidiosa e progressiva há 4 anos, limitação para calçar meias e sapatos (perda de flexão e rotação do quadril), dor noturna e em repouso, e radiografia com redução do espaço articular, esclerose subcondral e osteófitos são o quadro completo da osteoartrite do quadril. Após mais de seis meses de fisioterapia, anti-inflamatórios e opioides sem controle, a artroplastia total do quadril é o tratamento de escolha, com excelente alívio da dor. A osteonecrose (B) tem radiografia inicial normal ou com sinal do crescente e a artroplastia parcial se reserva a fraturas do colo em idosos frágeis. Não há fratura (C) nem os achados da osteoporose (D), que é radiograficamente silenciosa até fraturar.",
