      "edition": "tpi-2026-2-tpi2",
      "text": "Mulher de 65 anos, diabética e obesa, foi submetida à mastectomia por câncer de mama. No 5o dia de pós-operatório, presenta eritema e calor ao redor da incisão, com exsudato purulento e odor fétido. As glicemias capilares que a paciente fez em casa demonstraram diabetes fora do controle, com hiperglicemia em todas as medidas. O exame físico mostra uma área de deiscência parcial e presença de necrose superficial da ferida operatória. A paciente refere uso recente de suplementos de cálcio para osteoporose e está em terapia com insulina para o controle do diabetes. Adicionalmente, a paciente tem histórico de vasculite e faz uso de corticoides por via oral. Diante do caso clínico, assinale a alternativa que apresenta a terapêutica indicada.",
      "statement": "Mulher de 65 anos, diabética e obesa, foi submetida à mastectomia por câncer de mama. No 5o dia de pós-operatório, presenta eritema e calor ao redor da incisão, com exsudato purulento e odor fétido. As glicemias capilares que a paciente fez em casa demonstraram diabetes fora do controle, com hiperglicemia em todas as medidas. O exame físico mostra uma área de deiscência parcial e presença de necrose superficial da ferida operatória. A paciente refere uso recente de suplementos de cálcio para osteoporose e está em terapia com insulina para o controle do diabetes. Adicionalmente, a paciente tem histórico de vasculite e faz uso de corticoides por via oral. Diante do caso clínico, assinale a alternativa que apresenta a terapêutica indicada.",
