      "officialComment": "Infecção do sítio cirúrgico no quinto dia de mastectomia, com eritema, secreção purulenta fétida, deiscência parcial e necrose superficial, em diabética descompensada, obesa e em uso de corticoide por vasculite. Há tecido desvitalizado e paciente imunossuprimida: a conduta é desbridamento cirúrgico do tecido necrótico, coleta de cultura, antibiótico intravenoso de amplo espectro, cobrindo Gram-positivos, incluindo MRSA, Gram-negativos e anaeróbios, e controle glicêmico intensivo. Antibiótico oral com compressas (C e D) é insuficiente diante de necrose e imunossupressão. Aumentar o corticoide (B) piora a infecção e a cicatrização.",
      "explanation": "Infecção do sítio cirúrgico no quinto dia de mastectomia, com eritema, secreção purulenta fétida, deiscência parcial e necrose superficial, em diabética descompensada, obesa e em uso de corticoide por vasculite. Há tecido desvitalizado e paciente imunossuprimida: a conduta é desbridamento cirúrgico do tecido necrótico, coleta de cultura, antibiótico intravenoso de amplo espectro, cobrindo Gram-positivos, incluindo MRSA, Gram-negativos e anaeróbios, e controle glicêmico intensivo. Antibiótico oral com compressas (C e D) é insuficiente diante de necrose e imunossupressão. Aumentar o corticoide (B) piora a infecção e a cicatrização.",
