      "edition": "tpi-2026-2-tpi2",
      "text": "Mulher, 63 anos de idade, foi submetida à correção de hérnia incisional de laparotomia mediana. Foi feita a correção da hérnia com colocação de tela préaponeurótica (onlay) e drenagem fechada do subcutâneo. Recebeu alta hospitalar no 4o pós-operatório após a retirada do dreno. A paciente retorna em consulta ambulatorial, 7 dias após a alta, com queixa de abaulamento na incisão. Ao exame clínico, encontra-se em bom estado geral; abdome flácido, indolor à palpação, presença de coleção líquida no subcutâneo, sem sinais inflamatórios. Ultrassom de parede abdominal apresentado. Qual deve ser a conduta neste momento?",
