      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 32. Sem revisão clínica independente.",
      "officialComment": "TEV Abaulamento indolor, sem sinais inflamatórios, com coleção líquida anecoica no subcutâneo uma semana após hernioplastia incisional com tela onlay e retirada do dreno é seroma, complicação comum dessa técnica pela grande área de descolamento. A conduta é conservadora: cinta abdominal compressiva e observação, pois a maioria reabsorve em algumas semanas. Punção fica reservada a coleções volumosas e sintomáticas, sempre com técnica estéril, porque o risco maior é infectar a tela. Abrir a incisão (B) ou recolocar o dreno (C) expõem a tela a contaminação. Antibiótico (D) não tem indicação sem infecção.",
      "explanation": "TEV Abaulamento indolor, sem sinais inflamatórios, com coleção líquida anecoica no subcutâneo uma semana após hernioplastia incisional com tela onlay e retirada do dreno é seroma, complicação comum dessa técnica pela grande área de descolamento. A conduta é conservadora: cinta abdominal compressiva e observação, pois a maioria reabsorve em algumas semanas. Punção fica reservada a coleções volumosas e sintomáticas, sempre com técnica estéril, porque o risco maior é infectar a tela. Abrir a incisão (B) ou recolocar o dreno (C) expõem a tela a contaminação. Antibiótico (D) não tem indicação sem infecção.",
