      "edition": "tpi-2026-2-tpi2",
      "text": "Homem, 59 anos, refere empachamento e vômitos esporádicos que se intensificaram na última semana. Apresentou perda de 6 kg neste período. Nega alteração do hábito intestinal. Trabalha como secretário e na última semana pediu afastamento devido à fraqueza, apesar de realizar sozinho suas tarefas em casa. Tem diabete melito, hipertensão arterial e é tabagista (40 anos.maço). Teve infarto agudo do miocárdio há 7 meses, quando foi submetido à angioplastia e colocação de stent. Faz uso de aspirina, clopidogrel, atenolol, metformina e atorvastatina. Ao exame clínico, encontra-se em bom estado geral: IMC: 21 kg/m2; ausculta pulmonar e cardíaca sem alterações; abdome flácido, escavado e sem massas palpáveis; toque retal sem alterações. Exames laboratoriais: Hb 9,6 g/dL; Ht 29%; VCM 77 fL; HCM 25 pg; albumina 3,1 mg/dL. Realizada endoscopia digestiva alta, que evidenciou lesão estenosante em antro com difícil passagem do gastroscópio infantil. Foi indicado tratamento operatório. Quais são as medidas que devem ser adotadas no pré-operatório com relação ao clopidogrel e à metformina?",
      "statement": "Homem, 59 anos, refere empachamento e vômitos esporádicos que se intensificaram na última semana. Apresentou perda de 6 kg neste período. Nega alteração do hábito intestinal. Trabalha como secretário e na última semana pediu afastamento devido à fraqueza, apesar de realizar sozinho suas tarefas em casa. Tem diabete melito, hipertensão arterial e é tabagista (40 anos.maço). Teve infarto agudo do miocárdio há 7 meses, quando foi submetido à angioplastia e colocação de stent. Faz uso de aspirina, clopidogrel, atenolol, metformina e atorvastatina. Ao exame clínico, encontra-se em bom estado geral: IMC: 21 kg/m2; ausculta pulmonar e cardíaca sem alterações; abdome flácido, escavado e sem massas palpáveis; toque retal sem alterações. Exames laboratoriais: Hb 9,6 g/dL; Ht 29%; VCM 77 fL; HCM 25 pg; albumina 3,1 mg/dL. Realizada endoscopia digestiva alta, que evidenciou lesão estenosante em antro com difícil passagem do gastroscópio infantil. Foi indicado tratamento operatório. Quais são as medidas que devem ser adotadas no pré-operatório com relação ao clopidogrel e à metformina?",
