      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 70. Sem revisão clínica independente.",
      "officialComment": "Paciente com stent coronário implantado há 7 meses após infarto, em dupla antiagregação, com estenose gástrica tumoral que exige cirurgia. Após 6 meses de dupla antiagregação em síndrome coronariana aguda, o inibidor de P2Y12 pode ser suspenso para cirurgia não adiável: o clopidogrel é interrompido 5 dias antes, mantendose o AAS durante todo o perioperatório. A metformina é suspensa 24 a 48 horas antes, pelo risco de acidose láctica em situações de hipoperfusão, jejum e contraste, e retomada quando a dieta e a função renal estiverem normais. Manter o clopidogrel (C e D) eleva o sangramento operatório; manter a metformina (A) expõe ao risco metabólico.",
      "explanation": "Paciente com stent coronário implantado há 7 meses após infarto, em dupla antiagregação, com estenose gástrica tumoral que exige cirurgia. Após 6 meses de dupla antiagregação em síndrome coronariana aguda, o inibidor de P2Y12 pode ser suspenso para cirurgia não adiável: o clopidogrel é interrompido 5 dias antes, mantendose o AAS durante todo o perioperatório. A metformina é suspensa 24 a 48 horas antes, pelo risco de acidose láctica em situações de hipoperfusão, jejum e contraste, e retomada quando a dieta e a função renal estiverem normais. Manter o clopidogrel (C e D) eleva o sangramento operatório; manter a metformina (A) expõe ao risco metabólico.",
