      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 41. Sem revisão clínica independente.",
      "officialComment": "Homem que faz sexo com homens, com lesão de borda anal que cresceu a partir de uma verruga e se tornou ulcerada, dolorosa, sangrante e endurecida, tem o quadro do carcinoma espinocelular do canal anal, cujo principal fator de risco é a infecção persistente pelo HPV 16, mais frequente nessa população e em pessoas vivendo com HIV. O condiloma acuminado (A) é vegetante, indolor e não ulcera. O adenocarcinoma (C) é retal, mais alto, e não se apresenta como lesão de margem. A hemorroida interna grau IV (D) é prolapso mucoso irredutível, sem massa ulcerada. A conduta é biópsia e, confirmado, quimiorradioterapia (protocolo de Nigro), reservando a cirurgia para falha.",
      "explanation": "Homem que faz sexo com homens, com lesão de borda anal que cresceu a partir de uma verruga e se tornou ulcerada, dolorosa, sangrante e endurecida, tem o quadro do carcinoma espinocelular do canal anal, cujo principal fator de risco é a infecção persistente pelo HPV 16, mais frequente nessa população e em pessoas vivendo com HIV. O condiloma acuminado (A) é vegetante, indolor e não ulcera. O adenocarcinoma (C) é retal, mais alto, e não se apresenta como lesão de margem. A hemorroida interna grau IV (D) é prolapso mucoso irredutível, sem massa ulcerada. A conduta é biópsia e, confirmado, quimiorradioterapia (protocolo de Nigro), reservando a cirurgia para falha.",
