      "edition": "tpi-2026-2-tpi2",
      "text": "Uma criança do gênero masculino de 12 anos sofre queda da bicicleta e deu entrada no Pronto-Socorro 15 minutos após a ocorrência, apresentando um ferimento de 4,5 cm, superficial, acometendo pele e subcutâneo, em região pré-patelar direita. Há presença de sujidade (terra e grama) no ferimento. Cobertura antitetânica atualizada. Após limpeza do ferimento, qual tipo de fio cirúrgico seria a melhor escolha para essa situação?",
      "statement": "Uma criança do gênero masculino de 12 anos sofre queda da bicicleta e deu entrada no Pronto-Socorro 15 minutos após a ocorrência, apresentando um ferimento de 4,5 cm, superficial, acometendo pele e subcutâneo, em região pré-patelar direita. Há presença de sujidade (terra e grama) no ferimento. Cobertura antitetânica atualizada. Após limpeza do ferimento, qual tipo de fio cirúrgico seria a melhor escolha para essa situação?",
