      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 55. Sem revisão clínica independente.",
      "officialComment": "Ferimento contaminado por terra, superficial, atingindo pele e subcutâneo, em criança com vacinação antitetânica em dia: após limpeza abundante e desbridamento, a sutura da pele deve usar fio monofilamentar não absorvível, como náilon ou polipropileno. O monofilamento tem superfície lisa, com menor aderência bacteriana e menor reação tecidual, ao contrário dos trançados (A e B), que abrigam bactérias por capilaridade e aumentam o risco de infecção em ferida contaminada. Fios absorvíveis (B e D) na pele produzem mais reação inflamatória e não são a escolha para fechamento cutâneo em ferida suja. Os pontos são retirados em 10 a 14 dias em região de articulação.",
      "explanation": "Ferimento contaminado por terra, superficial, atingindo pele e subcutâneo, em criança com vacinação antitetânica em dia: após limpeza abundante e desbridamento, a sutura da pele deve usar fio monofilamentar não absorvível, como náilon ou polipropileno. O monofilamento tem superfície lisa, com menor aderência bacteriana e menor reação tecidual, ao contrário dos trançados (A e B), que abrigam bactérias por capilaridade e aumentam o risco de infecção em ferida contaminada. Fios absorvíveis (B e D) na pele produzem mais reação inflamatória e não são a escolha para fechamento cutâneo em ferida suja. Os pontos são retirados em 10 a 14 dias em região de articulação.",
