      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Uma mulher de 35 anos foi socorrida pelo resgate após incêndio no seu local de trabalho. A paciente trabalhava em um ambiente pequeno e fechado e foi retirada do local, agitada e confusa, após vinte minutos do início do incêndio. Sinais vitais no local: pressão arterial de 120 x 70 mmHg, frequência cardíaca de 95 bpm, frequência respiratória de 22 ipm, saturação de O2 de 96% em ar ambiente. Chega ao serviço de emergência em prancha rígida, com colar cervical e máscara de O2 com fluxo de 12 L/min. Queixa-se de dor em face e tórax. Respiração sem ruídos. Queimadura de face e região anterior e superior do tórax não circunferencial, saturação de O2 de 98%. Escala de coma de Glasgow: AO 4 RV 5 RM 6. Diante desse quadro, assinalea alternativa que descreve corretamente alteração(ões) do exame físico que é(são) indício(s) de gravidade e, respectivamente, a conduta prioritária no atendimento.",
      "statement": "Uma mulher de 35 anos foi socorrida pelo resgate após incêndio no seu local de trabalho. A paciente trabalhava em um ambiente pequeno e fechado e foi retirada do local, agitada e confusa, após vinte minutos do início do incêndio. Sinais vitais no local: pressão arterial de 120 x 70 mmHg, frequência cardíaca de 95 bpm, frequência respiratória de 22 ipm, saturação de O2 de 96% em ar ambiente. Chega ao serviço de emergência em prancha rígida, com colar cervical e máscara de O2 com fluxo de 12 L/min. Queixa-se de dor em face e tórax. Respiração sem ruídos. Queimadura de face e região anterior e superior do tórax não circunferencial, saturação de O2 de 98%. Escala de coma de Glasgow: AO 4 RV 5 RM 6. Diante desse quadro, assinalea alternativa que descreve corretamente alteração(ões) do exame físico que é(são) indício(s) de gravidade e, respectivamente, a conduta prioritária no atendimento.",
