      "officialComment": "Incêndio em ambiente fechado, queimadura de face e do tórax superior, dor em face e rouquidão apontam para lesão inalatória de via aérea superior, cuja evolução natural é o edema progressivo nas horas seguintes, quando a intubação se torna difícil. Cílios e vibrissas queimados, fuligem oral, escarro carbonáceo e rouquidão são os indícios de gravidade, e a conduta prioritária é a intubação orotraqueal precoce, enquanto a via aérea ainda é pérvia. Remover fuligem (A), aspirar orofaringe (C) e lidocaína (D) não tratam a ameaça real, que é a obstrução por edema.",
      "explanation": "Incêndio em ambiente fechado, queimadura de face e do tórax superior, dor em face e rouquidão apontam para lesão inalatória de via aérea superior, cuja evolução natural é o edema progressivo nas horas seguintes, quando a intubação se torna difícil. Cílios e vibrissas queimados, fuligem oral, escarro carbonáceo e rouquidão são os indícios de gravidade, e a conduta prioritária é a intubação orotraqueal precoce, enquanto a via aérea ainda é pérvia. Remover fuligem (A), aspirar orofaringe (C) e lidocaína (D) não tratam a ameaça real, que é a obstrução por edema.",
