      "text": "Paciente de 35 anos, vítima de acidente com veículo automotor. No serviço de emergência está instável, com pressão arterial sistólica de 60 mmHg; FC: 140 bpm. FAST negativo. Realizada uma radiografia de pelve mostrada a seguir. Colocada uma cinta pélvica, sem melhora hemodinâmica. Iniciado protocolo de transfusão maciça. Próximo passo a ser dado, dentre as opções abaixo, deverá ser:",
      "statement": "Paciente de 35 anos, vítima de acidente com veículo automotor. No serviço de emergência está instável, com pressão arterial sistólica de 60 mmHg; FC: 140 bpm. FAST negativo. Realizada uma radiografia de pelve mostrada a seguir. Colocada uma cinta pélvica, sem melhora hemodinâmica. Iniciado protocolo de transfusão maciça. Próximo passo a ser dado, dentre as opções abaixo, deverá ser:",
