      "officialComment": "Vítima de acidente automobilístico com pressão sistólica de 60 mmHg, radiografia com fratura pélvica instável, FAST negativo e ausência de resposta à cinta pélvica, já em transfusão maciça, tem hemorragia retroperitoneal de origem pélvica, na maioria das vezes venosa e óssea. Nesse paciente instável, o próximo passo é o tamponamento pré-peritoneal, rápido, feito no centro cirúrgico, seguido de angioembolização se o sangramento persistir. A arteriografia (B) de saída trata só o componente arterial, presente em 10 a 15% dos casos, e consome tempo que o paciente não tem. A laparotomia (A) não tem indicação com FAST negativo. A fixação interna (D) é tratamento definitivo, não da fase aguda; o fixador externo seria o método da urgência.",
