      "text": "Homem de 25 anos de idade, vítima de acidente motociclístico, apresenta dor perineal, sangue no meato uretral e incapacidade de urinar desde o acidente. Exame físico: escoriações perineais e hematoma escrotal em \"borboleta\". O próximo passo na abordagem diagnóstica é",
