      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 24. Sem revisão clínica independente.",
      "officialComment": "Trauma perineal com sangue no meato uretral, retenção urinária e hematoma escrotal em borboleta, limitado pela fáscia de Colles, é o quadro da lesão de uretra bulbar. A regra é não passar sonda às cegas: a sondagem pode transformar uma lesão parcial em completa (C). O exame indicado antes de qualquer sondagem é a uretrocistografia retrógrada, que define se há extravasamento e onde. Confirmada a lesão, drena-se a bexiga por cistostomia suprapúbica (B), mas indicá-la sem imagem pode ser desnecessário se a uretra estiver íntegra. A ultrassonografia vesical (A) só mede o volume e não avalia a uretra.",
      "explanation": "Trauma perineal com sangue no meato uretral, retenção urinária e hematoma escrotal em borboleta, limitado pela fáscia de Colles, é o quadro da lesão de uretra bulbar. A regra é não passar sonda às cegas: a sondagem pode transformar uma lesão parcial em completa (C). O exame indicado antes de qualquer sondagem é a uretrocistografia retrógrada, que define se há extravasamento e onde. Confirmada a lesão, drena-se a bexiga por cistostomia suprapúbica (B), mas indicá-la sem imagem pode ser desnecessário se a uretra estiver íntegra. A ultrassonografia vesical (A) só mede o volume e não avalia a uretra.",
