      "alternatives": [
        "Cistostomia supra-púbica.",
        "Sondagem vesical de demora.",
        "Nefrostomia bilateral guiada por radiointervenção.",
        "Cateterismo intermitente."
      ],
      "answer": "B",
      "correctAnswer": "B",
      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 48. Sem revisão clínica independente.",
      "officialComment": "Trauma raquimedular agudo em L3-L4 produz bexiga arreflexa com retenção urinária na fase de choque medular. Num politraumatizado, a drenagem vesical é necessária para monitorar a diurese e evitar hiperdistensão, e a sondagem vesical de demora é a conduta na fase aguda. Não há sinais de lesão uretral (sangue no meato, hematoma perineal, fratura de pelve), portanto a sondagem é segura e a cistostomia (A) não tem indicação. O cateterismo intermitente (D) é a estratégia da fase crônica da bexiga neurogênica, após a estabilização. A nefrostomia (C) não faz sentido sem obstrução do trato superior.",
      "explanation": "Trauma raquimedular agudo em L3-L4 produz bexiga arreflexa com retenção urinária na fase de choque medular. Num politraumatizado, a drenagem vesical é necessária para monitorar a diurese e evitar hiperdistensão, e a sondagem vesical de demora é a conduta na fase aguda. Não há sinais de lesão uretral (sangue no meato, hematoma perineal, fratura de pelve), portanto a sondagem é segura e a cistostomia (A) não tem indicação. O cateterismo intermitente (D) é a estratégia da fase crônica da bexiga neurogênica, após a estabilização. A nefrostomia (C) não faz sentido sem obstrução do trato superior.",
      "sourceCommentImported": true,
