      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Homem de 32 anos, vítima de trauma torácico contuso, por queda de bicicleta, foi levado à emergência por familiares. Na admissão, realizou tomografia de tórax, abdômen e pelve que mostrou apenas presença de derrame pleural volumoso à direita. Foi realizada toracostomia com tubo em selo d ́água, com relato de saída imediata de aproximadamente 1.000mL de sangue. O paciente apresentou melhora significativa e ficou em observação. Três horas após o procedimento, apresentou quadro de hipotensão arterial (PA = 90 x 50mmHg). O dreno de tórax apresentou drenagem de 800mL de secreção hemática nesse período. A conduta adequada, nesse caso, é:",
      "statement": "Homem de 32 anos, vítima de trauma torácico contuso, por queda de bicicleta, foi levado à emergência por familiares. Na admissão, realizou tomografia de tórax, abdômen e pelve que mostrou apenas presença de derrame pleural volumoso à direita. Foi realizada toracostomia com tubo em selo d ́água, com relato de saída imediata de aproximadamente 1.000mL de sangue. O paciente apresentou melhora significativa e ficou em observação. Três horas após o procedimento, apresentou quadro de hipotensão arterial (PA = 90 x 50mmHg). O dreno de tórax apresentou drenagem de 800mL de secreção hemática nesse período. A conduta adequada, nesse caso, é:",
      "opts": [
        "toracotomia direta de emergência",
        "nova drenagem pleural",
        "hemotransfusão",
        "laparotomia exploradora imediata"
      ],
      "alternatives": [
        "toracotomia direta de emergência",
        "nova drenagem pleural",
        "hemotransfusão",
        "laparotomia exploradora imediata"
      ],
