      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 47. Sem revisão clínica independente.",
      "officialComment": "Hemotórax com débito imediato de 1.000 mL pelo dreno e mais 800 mL em 3 horas, cerca de 270 mL por hora, com hipotensão, preenche os critérios de hemotórax maciço: drenagem inicial superior a 1.500 mL ou superior a 200 mL por hora por 2 a 4 horas, ou instabilidade persistente. A indicação é toracotomia de emergência para controle da fonte de sangramento. Nova drenagem (B) e hemotransfusão (C) não param o sangramento. A laparotomia (D) não se justifica: a tomografia de abdome e pelve foi normal.",
      "explanation": "Hemotórax com débito imediato de 1.000 mL pelo dreno e mais 800 mL em 3 horas, cerca de 270 mL por hora, com hipotensão, preenche os critérios de hemotórax maciço: drenagem inicial superior a 1.500 mL ou superior a 200 mL por hora por 2 a 4 horas, ou instabilidade persistente. A indicação é toracotomia de emergência para controle da fonte de sangramento. Nova drenagem (B) e hemotransfusão (C) não param o sangramento. A laparotomia (D) não se justifica: a tomografia de abdome e pelve foi normal.",
