      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 64. Sem revisão clínica independente.",
      "officialComment": "Adenocarcinoma de próstata com PSA de 8 ng/mL (abaixo de 10), Gleason 7 (3+4), grupo ISUP 2, e nódulo nos dois lobos restrito à próstata (T2c) é classificado como risco intermediário, favorável pela composição do Gleason. O paciente deve ser estadiado (cintilografia óssea e tomografia, ou PET-PSMA conforme disponibilidade) e, sem doença a distância, tratado com intenção curativa por prostatectomia radical ou radioterapia. A alternativa B erra ao chamar de baixo risco, que exige Gleason 6, PSA abaixo de 10 e T1T2a. A alternativa A erra ao propor radioterapia como melhor tratamento de doença metastática, que é a hormonioterapia. A alternativa D erra com o nunca: hormonioterapia adjuvante pode ser indicada conforme a patologia.",
      "explanation": "Adenocarcinoma de próstata com PSA de 8 ng/mL (abaixo de 10), Gleason 7 (3+4), grupo ISUP 2, e nódulo nos dois lobos restrito à próstata (T2c) é classificado como risco intermediário, favorável pela composição do Gleason. O paciente deve ser estadiado (cintilografia óssea e tomografia, ou PET-PSMA conforme disponibilidade) e, sem doença a distância, tratado com intenção curativa por prostatectomia radical ou radioterapia. A alternativa B erra ao chamar de baixo risco, que exige Gleason 6, PSA abaixo de 10 e T1T2a. A alternativa A erra ao propor radioterapia como melhor tratamento de doença metastática, que é a hormonioterapia. A alternativa D erra com o nunca: hormonioterapia adjuvante pode ser indicada conforme a patologia.",
