      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Mulher, 38 anos, nulípara, retorna ao ambulatório de ginecologia devido ao desejo de engravidar. Relata história de abortamento espontâneo há 7 meses, com necessidade de curetagem. Desde então não apresentou mais menstruação. Exames laboratoriais: TSH, prolactina e FSH todos dentro da normalidade; Beta-hCG negativo; espermograma do marido normal. Realizado teste do estrogênio e progesterona com resultado negativo. Considerando a principal hipótese diagnóstica, assinale a alternativa que apresenta a melhor conduta a ser seguida.",
      "statement": "Mulher, 38 anos, nulípara, retorna ao ambulatório de ginecologia devido ao desejo de engravidar. Relata história de abortamento espontâneo há 7 meses, com necessidade de curetagem. Desde então não apresentou mais menstruação. Exames laboratoriais: TSH, prolactina e FSH todos dentro da normalidade; Beta-hCG negativo; espermograma do marido normal. Realizado teste do estrogênio e progesterona com resultado negativo. Considerando a principal hipótese diagnóstica, assinale a alternativa que apresenta a melhor conduta a ser seguida.",
