      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 75. Sem revisão clínica independente.",
      "officialComment": "Amenorreia secundária que começou após curetagem por abortamento, com FSH, prolactina e TSH normais, beta-hCG negativo e teste de estrogênio e progesterona negativo, isto é, sem sangramento mesmo com estímulo hormonal completo, indica causa uterina: sinéquias intrauterinas, a síndrome de Asherman. O diagnóstico e o tratamento são feitos por histeroscopia com lise das aderências, seguida de estrogênio para regenerar o endométrio. Induzir ovulação (C) ou inseminar (D) é inútil sem cavidade endometrial funcional. Aguardar 12 meses (B) só atrasa o tratamento de uma paciente de 38 anos que deseja engravidar.",
      "explanation": "Amenorreia secundária que começou após curetagem por abortamento, com FSH, prolactina e TSH normais, beta-hCG negativo e teste de estrogênio e progesterona negativo, isto é, sem sangramento mesmo com estímulo hormonal completo, indica causa uterina: sinéquias intrauterinas, a síndrome de Asherman. O diagnóstico e o tratamento são feitos por histeroscopia com lise das aderências, seguida de estrogênio para regenerar o endométrio. Induzir ovulação (C) ou inseminar (D) é inútil sem cavidade endometrial funcional. Aguardar 12 meses (B) só atrasa o tratamento de uma paciente de 38 anos que deseja engravidar.",
