      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 67. Sem revisão clínica independente.",
      "officialComment": "Corrimento acinzentado, fluido, homogêneo e aderido às paredes, com pH de 5,0 e teste das aminas positivo, cumpre os critérios de Amsel para vaginose bacteriana. O protocolo brasileiro de IST indica metronidazol 500 mg de 12 em 12 horas por 7 dias ou, como alternativa de dose única, secnidazol 2 g por via oral, além do metronidazol gel. A tricomoníase (A) produz corrimento amarelo-esverdeado, bolhoso, com colpite e colo em framboesa. A candidíase (B) tem corrimento branco grumoso, prurido e pH normal, abaixo de 4,5. A chamada vaginite aeróbica (D) não corresponde ao quadro nem ao tratamento descrito.",
      "explanation": "Corrimento acinzentado, fluido, homogêneo e aderido às paredes, com pH de 5,0 e teste das aminas positivo, cumpre os critérios de Amsel para vaginose bacteriana. O protocolo brasileiro de IST indica metronidazol 500 mg de 12 em 12 horas por 7 dias ou, como alternativa de dose única, secnidazol 2 g por via oral, além do metronidazol gel. A tricomoníase (A) produz corrimento amarelo-esverdeado, bolhoso, com colpite e colo em framboesa. A candidíase (B) tem corrimento branco grumoso, prurido e pH normal, abaixo de 4,5. A chamada vaginite aeróbica (D) não corresponde ao quadro nem ao tratamento descrito.",
