      "edition": "tpi-2026-2-tpi2",
      "text": "Mulher, 24 anos, queixa-se de leucorreia acinzentada com odor desagradável que piora após atividade sexual. Refere início do quadro há 2 semanas. Exame ginecológico: conteúdo vaginal aumentado, acinzentado e bolhoso; colo uterino de aspecto epitelizado e usual; muco cervical filante e transparente. Realizou-se fita de pH vaginal com resultado de 6,5. Pode-se afirmar que a hipótese diagnóstica mais provável e o achado que melhor auxiliaria a corroborá-la são:",
      "statement": "Mulher, 24 anos, queixa-se de leucorreia acinzentada com odor desagradável que piora após atividade sexual. Refere início do quadro há 2 semanas. Exame ginecológico: conteúdo vaginal aumentado, acinzentado e bolhoso; colo uterino de aspecto epitelizado e usual; muco cervical filante e transparente. Realizou-se fita de pH vaginal com resultado de 6,5. Pode-se afirmar que a hipótese diagnóstica mais provável e o achado que melhor auxiliaria a corroborá-la são:",
