      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 100. Sem revisão clínica independente.",
      "officialComment": "Leucorreia acinzentada, bolhosa, de odor desagradável que piora após o coito, porque o sêmen alcalino libera as aminas voláteis, com pH vaginal de 6,5 e colo de aspecto normal, é vaginose bacteriana. O achado que melhor a confirma é a presença de clue cells, células epiteliais recobertas por cocobacilos, no exame a fresco, completando os critérios de Amsel; o escore de Nugent no Gram é a alternativa. A tricomoníase (B) cursa com corrimento amarelo-esverdeado, colpite e colo em framboesa, com o parasita móvel a fresco. A candidíase (D) tem pH normal e corrimento branco grumoso. A cervicite gonocócica (A) produz secreção mucopurulenta endocervical com colo friável.",
      "explanation": "Leucorreia acinzentada, bolhosa, de odor desagradável que piora após o coito, porque o sêmen alcalino libera as aminas voláteis, com pH vaginal de 6,5 e colo de aspecto normal, é vaginose bacteriana. O achado que melhor a confirma é a presença de clue cells, células epiteliais recobertas por cocobacilos, no exame a fresco, completando os critérios de Amsel; o escore de Nugent no Gram é a alternativa. A tricomoníase (B) cursa com corrimento amarelo-esverdeado, colpite e colo em framboesa, com o parasita móvel a fresco. A candidíase (D) tem pH normal e corrimento branco grumoso. A cervicite gonocócica (A) produz secreção mucopurulenta endocervical com colo friável.",
