      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 42. Sem revisão clínica independente.",
      "officialComment": "Nódulo palpável, doloroso, na menacme, que a ultrassonografia caracteriza como cisto simples de 5,5 cm, anecoico e bem delimitado (BI-RADS 2), não exige biópsia: a punção aspirativa por agulha fina esvazia o cisto, alivia a dor e confirma a natureza benigna; o líquido só vai para citologia se for sanguinolento ou se restar massa. A core biopsy (B) é para lesões sólidas. A exérese (A) não se justifica em cisto simples. Repetir a ultrassonografia em 6 meses (D) ignora a mastalgia e o volume do cisto, que causam o incômodo da paciente.",
      "explanation": "Nódulo palpável, doloroso, na menacme, que a ultrassonografia caracteriza como cisto simples de 5,5 cm, anecoico e bem delimitado (BI-RADS 2), não exige biópsia: a punção aspirativa por agulha fina esvazia o cisto, alivia a dor e confirma a natureza benigna; o líquido só vai para citologia se for sanguinolento ou se restar massa. A core biopsy (B) é para lesões sólidas. A exérese (A) não se justifica em cisto simples. Repetir a ultrassonografia em 6 meses (D) ignora a mastalgia e o volume do cisto, que causam o incômodo da paciente.",
