      "text": "Mulher, 32 anos de idade, vai em consulta ginecológica devido a dismenorreia progressiva desde a menarca e dispareunia. Ao exame físico nota-se espessamento do septo retovaginal. A paciente trouxe uma ultrassonografia transvaginal que caracterizava presença de cisto com conteúdo hemático no ovário direito, medindo 30 mm de diâmetro. O próximo passo propedêutico é:",
      "statement": "Mulher, 32 anos de idade, vai em consulta ginecológica devido a dismenorreia progressiva desde a menarca e dispareunia. Ao exame físico nota-se espessamento do septo retovaginal. A paciente trouxe uma ultrassonografia transvaginal que caracterizava presença de cisto com conteúdo hemático no ovário direito, medindo 30 mm de diâmetro. O próximo passo propedêutico é:",
