      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 85. Sem revisão clínica independente.",
      "officialComment": "Dismenorreia progressiva desde a menarca, dispareunia de profundidade, espessamento do septo retovaginal ao exame e endometrioma no ovário direito compõem o quadro de endometriose profunda. O próximo passo é o mapeamento das lesões por ressonância magnética de pelve (ou ultrassonografia especializada com preparo intestinal), que define a extensão, o acometimento intestinal, ureteral e vesical e planeja o tratamento. Puncionar o endometrioma (A) é contraindicado: não confirma diagnóstico, recidiva e pode infectar. A tomografia (B) tem baixa acurácia para endometriose. A colonoscopia (C) só é útil quando há suspeita de invasão da mucosa, e vem depois do mapeamento.",
      "explanation": "Dismenorreia progressiva desde a menarca, dispareunia de profundidade, espessamento do septo retovaginal ao exame e endometrioma no ovário direito compõem o quadro de endometriose profunda. O próximo passo é o mapeamento das lesões por ressonância magnética de pelve (ou ultrassonografia especializada com preparo intestinal), que define a extensão, o acometimento intestinal, ureteral e vesical e planeja o tratamento. Puncionar o endometrioma (A) é contraindicado: não confirma diagnóstico, recidiva e pode infectar. A tomografia (B) tem baixa acurácia para endometriose. A colonoscopia (C) só é útil quando há suspeita de invasão da mucosa, e vem depois do mapeamento.",
