      "edition": "tpi-2026-2-tpi2",
      "text": "Paciente de 62 anos consultou por perda urinária aos pequenos esforços. Embora não houvesse urgência urinária, relatou não conseguir segurar a urina até chegar ao banheiro. Informou fazer uso de losartana, hidroclorotiazida e insulina há mais de 10 anos. Ao exame, não havia distopia urinária, mas, sim perda no pequeno esforço à manobra de Valsalva, pressão de perda de 80 cmH2O e resíduo urinário de 400ml. Seu IMC era de 34 kg/m2. O diagnóstico mais provável é incontinência urinária",
      "statement": "Paciente de 62 anos consultou por perda urinária aos pequenos esforços. Embora não houvesse urgência urinária, relatou não conseguir segurar a urina até chegar ao banheiro. Informou fazer uso de losartana, hidroclorotiazida e insulina há mais de 10 anos. Ao exame, não havia distopia urinária, mas, sim perda no pequeno esforço à manobra de Valsalva, pressão de perda de 80 cmH2O e resíduo urinário de 400ml. Seu IMC era de 34 kg/m2. O diagnóstico mais provável é incontinência urinária",
