      "officialComment": "Perda urinária aos esforços, mas com resíduo pós-miccional de 400 mL e pressão de perda de 80 cmH2O (esfíncter competente), em diabética há mais de 10 anos, indica bexiga hipoativa por cistopatia diabética com incontinência por transbordamento: a bexiga superdistendida perde urina ao aumento da pressão abdominal. A deficiência esfincteriana (A) se caracteriza por pressão de perda baixa, abaixo de 60 cmH2O, e sem resíduo. A incontinência transitória (B) decorre de causas agudas reversíveis, como infecção, delirium ou fármacos. Não existe a categoria de desvio (D); a perda contínua extrauretral é a fístula. A conduta é cateterismo intermitente, revisão de medicações e tratamento da neuropatia.",
      "explanation": "Perda urinária aos esforços, mas com resíduo pós-miccional de 400 mL e pressão de perda de 80 cmH2O (esfíncter competente), em diabética há mais de 10 anos, indica bexiga hipoativa por cistopatia diabética com incontinência por transbordamento: a bexiga superdistendida perde urina ao aumento da pressão abdominal. A deficiência esfincteriana (A) se caracteriza por pressão de perda baixa, abaixo de 60 cmH2O, e sem resíduo. A incontinência transitória (B) decorre de causas agudas reversíveis, como infecção, delirium ou fármacos. Não existe a categoria de desvio (D); a perda contínua extrauretral é a fístula. A conduta é cateterismo intermitente, revisão de medicações e tratamento da neuropatia.",
