      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 65. Sem revisão clínica independente.",
      "officialComment": "Dismenorreia moderada nos dois primeiros dias do fluxo, surgida após a inserção do DIU de cobre, com exame normal, ausência de infecção e dispositivo bem posicionado, é efeito esperado do método, que aumenta o fluxo e a cólica sobretudo no primeiro ano. A conduta é manter o DIU e prescrever anti-inflamatório não esteroidal nos primeiros dias do ciclo, o que reduz a dor e o sangramento. Remover o DIU (A e D) só se a dor persistir e for intolerável. Não há sinais de doença inflamatória pélvica que justifiquem testar e aguardar (B), e o contraceptivo combinado (A) não é necessário.",
      "explanation": "Dismenorreia moderada nos dois primeiros dias do fluxo, surgida após a inserção do DIU de cobre, com exame normal, ausência de infecção e dispositivo bem posicionado, é efeito esperado do método, que aumenta o fluxo e a cólica sobretudo no primeiro ano. A conduta é manter o DIU e prescrever anti-inflamatório não esteroidal nos primeiros dias do ciclo, o que reduz a dor e o sangramento. Remover o DIU (A e D) só se a dor persistir e for intolerável. Não há sinais de doença inflamatória pélvica que justifiquem testar e aguardar (B), e o contraceptivo combinado (A) não é necessário.",
