      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Mulher de 42 anos, G1C1, laqueada, vem encaminhada a serviço terciário devido a sangramento uterino anormal iniciado há 2 anos, com aumento de volume e duração da menstruação, com piora nos últimos meses. Está em uso de análogo do GnRH há 9 meses com resolução do sangramento. Apresentando sintomas vasomotores e ressecamento vaginal. Comorbidades: HAS bem controlada com uso de medicação, obesidade grau 1. Achados relevantes do exame físico: útero aumentado de volume ao toque vaginal. Exames complementares (realizados no início dos sintomas): ultrassonografia transvaginal mostrando leiomiomatose com presença de múltiplos leiomiomas subserosos e intramurais com volume uterino de 300 cm3. Qual a conduta mais adequada neste caso?",
      "statement": "Mulher de 42 anos, G1C1, laqueada, vem encaminhada a serviço terciário devido a sangramento uterino anormal iniciado há 2 anos, com aumento de volume e duração da menstruação, com piora nos últimos meses. Está em uso de análogo do GnRH há 9 meses com resolução do sangramento. Apresentando sintomas vasomotores e ressecamento vaginal. Comorbidades: HAS bem controlada com uso de medicação, obesidade grau 1. Achados relevantes do exame físico: útero aumentado de volume ao toque vaginal. Exames complementares (realizados no início dos sintomas): ultrassonografia transvaginal mostrando leiomiomatose com presença de múltiplos leiomiomas subserosos e intramurais com volume uterino de 300 cm3. Qual a conduta mais adequada neste caso?",
      "opts": [
        "Iniciar contraceptivo combinado.",
        "Indicar histeroscopia cirúrgica.",
        "Iniciar contraceptivo de progestagênio isolado.",
        "Manter análogo de GnRH."
      ],
      "alternatives": [
        "Iniciar contraceptivo combinado.",
        "Indicar histeroscopia cirúrgica.",
        "Iniciar contraceptivo de progestagênio isolado.",
        "Manter análogo de GnRH."
      ],
      "answer": "C",
      "correctAnswer": "C",
      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 46. Sem revisão clínica independente.",
      "officialComment": "Mulher de 42 anos, laqueada, hipertensa e obesa, com miomatose de miomas subserosos e intramurais e sangramento controlado por análogo de GnRH há 9 meses, já apresenta os efeitos do hipoestrogenismo. O análogo não pode ser mantido além de 6 meses sem terapia de reposição (D). O contraceptivo combinado (A) é contraindicado pela hipertensão e obesidade, e a laqueadura torna a contracepção irrelevante. A histeroscopia (B) trata miomas submucosos, não os subserosos e intramurais descritos. O progestagênio isolado, oral ou como DIU de levonorgestrel, controla o sangramento sem estrogênio e é a melhor opção clínica; o tratamento definitivo, se falhar, é a histerectomia.",
      "explanation": "Mulher de 42 anos, laqueada, hipertensa e obesa, com miomatose de miomas subserosos e intramurais e sangramento controlado por análogo de GnRH há 9 meses, já apresenta os efeitos do hipoestrogenismo. O análogo não pode ser mantido além de 6 meses sem terapia de reposição (D). O contraceptivo combinado (A) é contraindicado pela hipertensão e obesidade, e a laqueadura torna a contracepção irrelevante. A histeroscopia (B) trata miomas submucosos, não os subserosos e intramurais descritos. O progestagênio isolado, oral ou como DIU de levonorgestrel, controla o sangramento sem estrogênio e é a melhor opção clínica; o tratamento definitivo, se falhar, é a histerectomia.",
