      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 87. Sem revisão clínica independente.",
      "officialComment": "Citopatológico com células glandulares atípicas (AGC) tem conduta definida pelas diretrizes brasileiras: encaminhar para colposcopia com avaliação do canal endocervical, e, em mulheres com 35 anos ou mais ou com sangramento anormal, como esta paciente com fluxo aumentado, investigar também o endométrio com ultrassonografia transvaginal e biópsia. Entre as hipóteses, a lesão glandular pré-invasiva, o adenocarcinoma in situ, é a que exige exclusão imediata. Repetir o citopatológico em 6 meses (B e C) é conduta para atipias escamosas de significado indeterminado, nunca para AGC. A infecção pelo HIV (D) não produz atipia glandular; ela apenas exige seguimento mais rigoroso.",
      "explanation": "Citopatológico com células glandulares atípicas (AGC) tem conduta definida pelas diretrizes brasileiras: encaminhar para colposcopia com avaliação do canal endocervical, e, em mulheres com 35 anos ou mais ou com sangramento anormal, como esta paciente com fluxo aumentado, investigar também o endométrio com ultrassonografia transvaginal e biópsia. Entre as hipóteses, a lesão glandular pré-invasiva, o adenocarcinoma in situ, é a que exige exclusão imediata. Repetir o citopatológico em 6 meses (B e C) é conduta para atipias escamosas de significado indeterminado, nunca para AGC. A infecção pelo HIV (D) não produz atipia glandular; ela apenas exige seguimento mais rigoroso.",
