      "officialComment": "Massa ovariana cística em mulher jovem com conteúdo hiperecogênico e sombra acústica posterior é a descrição ultrassonográfica do teratoma cístico maduro (cisto dermoide): gordura, cabelo, calcificação ou dente produzem o sinal da ponta do iceberg e a sombra. É o tumor de células germinativas mais comum e a principal complicação é a torção, que a dor intermitente já sugere. O cistoadenoma mucinoso (A) é multiloculado e volumoso; o seroso (B) é anecoico, unilocular e de paredes finas; o fibroma (C) é sólido, hipoecoico e se associa à síndrome de Meigs. O tratamento é a cistectomia com preservação do ovário.",
      "explanation": "Massa ovariana cística em mulher jovem com conteúdo hiperecogênico e sombra acústica posterior é a descrição ultrassonográfica do teratoma cístico maduro (cisto dermoide): gordura, cabelo, calcificação ou dente produzem o sinal da ponta do iceberg e a sombra. É o tumor de células germinativas mais comum e a principal complicação é a torção, que a dor intermitente já sugere. O cistoadenoma mucinoso (A) é multiloculado e volumoso; o seroso (B) é anecoico, unilocular e de paredes finas; o fibroma (C) é sólido, hipoecoico e se associa à síndrome de Meigs. O tratamento é a cistectomia com preservação do ovário.",
