      "text": "Primigesta com 40 semanas de gestação refere contrações há três horas e nega perdas vaginais. Refere pré-natal sem intercorrências, nega doenças crônicas e uso de medicações. Ao exame: PA: 130x80mmHg, altura uterina: 36 cm, 3 contrações em 10 minutos, BCF: 140 a 80 bpm, toque vaginal: colo 50% apagado, 4 cm de dilatação, cefálico, bolsa íntegra. Realizado cardiotocografia, cujo traçado é mostrado abaixo: Pela análise do traçado, assinale a alternativa que apresenta o diagnóstico CORRETO e sua fisiopatologia:",
      "statement": "Primigesta com 40 semanas de gestação refere contrações há três horas e nega perdas vaginais. Refere pré-natal sem intercorrências, nega doenças crônicas e uso de medicações. Ao exame: PA: 130x80mmHg, altura uterina: 36 cm, 3 contrações em 10 minutos, BCF: 140 a 80 bpm, toque vaginal: colo 50% apagado, 4 cm de dilatação, cefálico, bolsa íntegra. Realizado cardiotocografia, cujo traçado é mostrado abaixo: Pela análise do traçado, assinale a alternativa que apresenta o diagnóstico CORRETO e sua fisiopatologia:",
