      "officialComment": "O traçado mostra desacelerações que se iniciam depois do pico da contração e só retornam à linha de base após o seu término, com o nadir defasado em relação ao pico: são desacelerações tardias (DIP II). O mecanismo é a insuficiência uteroplacentária: a contração reduz o fluxo no espaço interviloso e, num feto com reserva limitada, produz hipóxia transitória que ativa quimiorreceptores e causa a queda tardia da frequência. As DIP I (C e D) coincidem com a contração e decorrem da compressão do polo cefálico, sem hipóxia. A compressão do cordão (B) produz desacelerações variáveis, abruptas e em V. A conduta é reanimação intrauterina e avaliação da via de parto.",
