      "text": "Gestante, 37 semanas, internada na maternidade há 24 horas, encontra-se na fase latente do trabalho de parto. Ao exame: febre de 38,5°C, taquicardia materna (105 bpm), líquido amniótico turvo e taquicardia fetal (170 bpm); ao toque vaginal, foi observado colo grosso, posterior, 1 cm de dilatação. De acordo com o diagnóstico do caso, assinale a afirmativa correta.",
