      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 43. Sem revisão clínica independente.",
      "officialComment": "Febre de 38,5 °C, taquicardia materna e fetal e líquido amniótico turvo em gestante internada em trabalho de parto definem corioamnionite. O tratamento é antibiótico intravenoso de amplo espectro, classicamente ampicilina com gentamicina, e a resolução do parto independentemente da idade gestacional, aqui 37 semanas: induz-se o parto vaginal, reservando a cesárea às indicações obstétricas. Aguardar com antitérmico (A) e aguardar com antibiótico (C) mantêm o feto no ambiente infectado. Tocolítico (B) é contraindicado na infecção intra-amniótica.",
