      "officialComment": "Dor abdominal súbita e intensa, útero com tônus aumentado sem atividade rítmica, sangramento escuro em pequena quantidade, hipertensão não tratada e bradicardia fetal (112 bpm) compõem o quadro do descolamento prematuro de placenta, cuja principal causa é a hipertensão. A placenta prévia (C) sangra vermelho vivo, indolor, com útero relaxado. O trabalho de parto prematuro (B) tem contrações rítmicas sem hipertonia nem sangramento escuro. A doença trofoblástica (A) é problema da primeira metade. Com feto vivo e sinais de sofrimento, a conduta é a resolução imediata pela via mais rápida, em geral cesárea com 2 cm de dilatação.",
      "explanation": "Dor abdominal súbita e intensa, útero com tônus aumentado sem atividade rítmica, sangramento escuro em pequena quantidade, hipertensão não tratada e bradicardia fetal (112 bpm) compõem o quadro do descolamento prematuro de placenta, cuja principal causa é a hipertensão. A placenta prévia (C) sangra vermelho vivo, indolor, com útero relaxado. O trabalho de parto prematuro (B) tem contrações rítmicas sem hipertonia nem sangramento escuro. A doença trofoblástica (A) é problema da primeira metade. Com feto vivo e sinais de sofrimento, a conduta é a resolução imediata pela via mais rápida, em geral cesárea com 2 cm de dilatação.",
