      "text": "Mulher, 40 anos de idade, no quarto período de um parto cefálico espontâneo, apresenta sangramento vaginal intenso. Diagnosticada com pré-eclâmpsia, está em uso de metildopa 2g/dia. Exame físico: PA 100 x 60 mmHg, FC 120bpm, útero 3cm acima da cicatriz umbilical e amolecido. Além da punção de 2 acessos calibrosos, infusão de cristaloides, qual é a conduta mais adequada?",
      "statement": "Mulher, 40 anos de idade, no quarto período de um parto cefálico espontâneo, apresenta sangramento vaginal intenso. Diagnosticada com pré-eclâmpsia, está em uso de metildopa 2g/dia. Exame físico: PA 100 x 60 mmHg, FC 120bpm, útero 3cm acima da cicatriz umbilical e amolecido. Além da punção de 2 acessos calibrosos, infusão de cristaloides, qual é a conduta mais adequada?",
