      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 76. Sem revisão clínica independente.",
      "officialComment": "Sangramento intenso no quarto período, útero acima da cicatriz umbilical e amolecido, taquicardia: hemorragia pós-parto por atonia uterina. A paciente tem pré-eclâmpsia, o que contraindica a metilergometrina (A). O tratamento é ocitocina intravenosa em dose terapêutica (bolus e infusão de 20 a 40 UI), ácido tranexâmico 1 g intravenoso nas primeiras 3 horas e misoprostol 800 mcg por via retal ou sublingual como uterotônico adicional, com massagem uterina e compressão bimanual. A ocitocina de 10 UI intramuscular (B) é a dose profilática, insuficiente para tratar. A tração controlada do cordão (C) pertence ao terceiro período; a placenta já saiu.",
      "explanation": "Sangramento intenso no quarto período, útero acima da cicatriz umbilical e amolecido, taquicardia: hemorragia pós-parto por atonia uterina. A paciente tem pré-eclâmpsia, o que contraindica a metilergometrina (A). O tratamento é ocitocina intravenosa em dose terapêutica (bolus e infusão de 20 a 40 UI), ácido tranexâmico 1 g intravenoso nas primeiras 3 horas e misoprostol 800 mcg por via retal ou sublingual como uterotônico adicional, com massagem uterina e compressão bimanual. A ocitocina de 10 UI intramuscular (B) é a dose profilática, insuficiente para tratar. A tração controlada do cordão (C) pertence ao terceiro período; a placenta já saiu.",
