      "text": "Primigesta com 30 semanas de gestação, sem histórico de epilepsia, veio à UPA queixando-se de cefaleia e visão turva. À avaliação inicial, a pressão arterial era de 160/110 mmHg. Enquanto a enfermeira chamava o médico, a paciente teve uma convulsão tônico-clônica. Imediatamente recebeu 4,0 g de sulfato de magnésio intravenoso para tratamento de eclâmpsia, e o quadro foi estabilizado. Após 15 minutos, novo episódio convulsivo ocorreu. Em situações como essa, a conduta mais adequada para reduzir a chance de novas convulsões é administrar, por via intravenosa,",
      "statement": "Primigesta com 30 semanas de gestação, sem histórico de epilepsia, veio à UPA queixando-se de cefaleia e visão turva. À avaliação inicial, a pressão arterial era de 160/110 mmHg. Enquanto a enfermeira chamava o médico, a paciente teve uma convulsão tônico-clônica. Imediatamente recebeu 4,0 g de sulfato de magnésio intravenoso para tratamento de eclâmpsia, e o quadro foi estabilizado. Após 15 minutos, novo episódio convulsivo ocorreu. Em situações como essa, a conduta mais adequada para reduzir a chance de novas convulsões é administrar, por via intravenosa,",
