      "officialComment": "Eclâmpsia tratada com dose de ataque de 4 g de sulfato de magnésio que apresenta nova convulsão após 15 minutos: a conduta é repetir um bolus de 2 g (até 4 g) de sulfato de magnésio por via intravenosa e manter a infusão contínua, pois o magnésio é superior aos anticonvulsivantes clássicos na prevenção de recorrência, como mostraram os ensaios Collaborative Eclampsia e Magpie. Fenitoína (A), fenobarbital (B) e diazepam (D) ficam reservados às convulsões refratárias ao magnésio. Após estabilizar a mãe, programa-se a resolução da gestação.",
      "explanation": "Eclâmpsia tratada com dose de ataque de 4 g de sulfato de magnésio que apresenta nova convulsão após 15 minutos: a conduta é repetir um bolus de 2 g (até 4 g) de sulfato de magnésio por via intravenosa e manter a infusão contínua, pois o magnésio é superior aos anticonvulsivantes clássicos na prevenção de recorrência, como mostraram os ensaios Collaborative Eclampsia e Magpie. Fenitoína (A), fenobarbital (B) e diazepam (D) ficam reservados às convulsões refratárias ao magnésio. Após estabilizar a mãe, programa-se a resolução da gestação.",
