      "edition": "tpi-2026-2-tpi2",
      "text": "Puérpera, 25 anos, primípara, comparece ao ambulatório 10 dias após parto vaginal sem complicações. Relata sangramento vaginal em pequena quantidade, de coloração amarelada, e desconforto perineal leve. Ao exame físico, observa-se episiorrafia íntegra, sem sinais de infecção ou hematomas. O fundo uterino não é palpável no abdome. Paciente está afebril e hemodinamicamente estável. Qual é a conduta mais adequada nesse momento?",
      "statement": "Puérpera, 25 anos, primípara, comparece ao ambulatório 10 dias após parto vaginal sem complicações. Relata sangramento vaginal em pequena quantidade, de coloração amarelada, e desconforto perineal leve. Ao exame físico, observa-se episiorrafia íntegra, sem sinais de infecção ou hematomas. O fundo uterino não é palpável no abdome. Paciente está afebril e hemodinamicamente estável. Qual é a conduta mais adequada nesse momento?",
