      "officialComment": "Dez dias após parto vaginal sem complicações, a puérpera apresenta lóquios em pequena quantidade e amarelados (lóquios serosos, evoluindo para alba), útero já não palpável acima do púbis, episiorrafia íntegra, afebril e estável: é o puerpério fisiológico. A conduta é tranquilizar e orientar sobre cuidados perineais, evolução dos lóquios, amamentação e sinais de alerta. A ultrassonografia (A) não tem indicação sem sangramento anormal. Não há febre, dor uterina nem lóquios fétidos que sugiram endometrite (C). O hemograma (D) não se justifica sem sintomas de anemia.",
      "explanation": "Dez dias após parto vaginal sem complicações, a puérpera apresenta lóquios em pequena quantidade e amarelados (lóquios serosos, evoluindo para alba), útero já não palpável acima do púbis, episiorrafia íntegra, afebril e estável: é o puerpério fisiológico. A conduta é tranquilizar e orientar sobre cuidados perineais, evolução dos lóquios, amamentação e sinais de alerta. A ultrassonografia (A) não tem indicação sem sangramento anormal. Não há febre, dor uterina nem lóquios fétidos que sugiram endometrite (C). O hemograma (D) não se justifica sem sintomas de anemia.",
