      "text": "Primigesta de 19 anos apresentou elevação da pressão arterial a partir de 26 semanas. Com 34 semanas, está em uso de metildopa 2 g/dia. Exames: PA 144 x 95 mmHg; proteinúria 700 mg/24h; ultrassom: peso fetal no percentil 2,5, oligoâmnio leve, diástole zero no Doppler da artéria umbilical e vasodilatação na artéria cerebral média. A conduta correta deve ser:",
      "statement": "Primigesta de 19 anos apresentou elevação da pressão arterial a partir de 26 semanas. Com 34 semanas, está em uso de metildopa 2 g/dia. Exames: PA 144 x 95 mmHg; proteinúria 700 mg/24h; ultrassom: peso fetal no percentil 2,5, oligoâmnio leve, diástole zero no Doppler da artéria umbilical e vasodilatação na artéria cerebral média. A conduta correta deve ser:",
