      "officialComment": "Pré-eclâmpsia com 34 semanas, em uso de metildopa, com restrição de crescimento fetal grave (percentil 2,5), oligoâmnio e diástole zero na artéria umbilical com centralização (vasodilatação da cerebral média). A diástole zero indica alto risco de óbito fetal e, a partir de 34 semanas, a conduta é a resolução da gestação após discutir a via de parto; o ducto venoso (D) orienta o momento do parto apenas abaixo de 32 a 34 semanas. Corticoide (A e C) não é indicado de rotina a partir de 34 semanas e, sobretudo, não deve adiar a resolução. Associar anti-hipertensivo (A e D) trata a mãe, não o comprometimento placentário.",
      "explanation": "Pré-eclâmpsia com 34 semanas, em uso de metildopa, com restrição de crescimento fetal grave (percentil 2,5), oligoâmnio e diástole zero na artéria umbilical com centralização (vasodilatação da cerebral média). A diástole zero indica alto risco de óbito fetal e, a partir de 34 semanas, a conduta é a resolução da gestação após discutir a via de parto; o ducto venoso (D) orienta o momento do parto apenas abaixo de 32 a 34 semanas. Corticoide (A e C) não é indicado de rotina a partir de 34 semanas e, sobretudo, não deve adiar a resolução. Associar anti-hipertensivo (A e D) trata a mãe, não o comprometimento placentário.",
