      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Primigesta, 29 anos de idade, idade gestacional de 11 semanas, comparece à consulta de pré-natal trazendo resultado de sorologias de toxoplasmose, realizado há sete dias, apresentando IgG negativo e IgM positivo. Considerando o contexto clínico, a conduta CORRETA neste momento é:",
      "statement": "Primigesta, 29 anos de idade, idade gestacional de 11 semanas, comparece à consulta de pré-natal trazendo resultado de sorologias de toxoplasmose, realizado há sete dias, apresentando IgG negativo e IgM positivo. Considerando o contexto clínico, a conduta CORRETA neste momento é:",
