      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 66. Sem revisão clínica independente.",
      "officialComment": "IgM reagente com IgG não reagente para toxoplasmose na 11a semana pode significar infecção muito recente, antes da soroconversão do IgG, ou IgM falso-positivo. O protocolo do Ministério da Saúde manda repetir a sorologia em 2 a 3 semanas para ver se o IgG positiva, iniciando desde já espiramicina, que reduz a transmissão placentária, enquanto o diagnóstico se define. O teste de avidez (C e D) só se aplica quando o IgG é reagente, pois mede a maturação desse anticorpo. O esquema tríplice (A e C) é reservado à infecção fetal comprovada ou à infecção materna após 16 a 18 semanas.",
      "explanation": "IgM reagente com IgG não reagente para toxoplasmose na 11a semana pode significar infecção muito recente, antes da soroconversão do IgG, ou IgM falso-positivo. O protocolo do Ministério da Saúde manda repetir a sorologia em 2 a 3 semanas para ver se o IgG positiva, iniciando desde já espiramicina, que reduz a transmissão placentária, enquanto o diagnóstico se define. O teste de avidez (C e D) só se aplica quando o IgG é reagente, pois mede a maturação desse anticorpo. O esquema tríplice (A e C) é reservado à infecção fetal comprovada ou à infecção materna após 16 a 18 semanas.",
