      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "Primigesta, 28 anos, com 40 semanas e 2 dias de gestação, comparece ao hospital em trabalho de parto. Relata contrações uterinas regulares há 6 horas, com intervalos de 3 minutos e duração média de 60 segundos. Ao exame obstétrico, verifica-se dilatação cervical de 4 cm, esvaecimento (apagamento) completo do colo e bolsa íntegra. O líquido amniótico é claro, com grumos. A paciente está hemodinamicamente estável e sem sinais de sofrimento fetal. Após 4 horas de evolução, observa-se que a dilatação cervical permanece em 4 cm, apesar da manutenção das contrações regulares. Qual é a conduta mais adequada nesse momento?",
      "statement": "Primigesta, 28 anos, com 40 semanas e 2 dias de gestação, comparece ao hospital em trabalho de parto. Relata contrações uterinas regulares há 6 horas, com intervalos de 3 minutos e duração média de 60 segundos. Ao exame obstétrico, verifica-se dilatação cervical de 4 cm, esvaecimento (apagamento) completo do colo e bolsa íntegra. O líquido amniótico é claro, com grumos. A paciente está hemodinamicamente estável e sem sinais de sofrimento fetal. Após 4 horas de evolução, observa-se que a dilatação cervical permanece em 4 cm, apesar da manutenção das contrações regulares. Qual é a conduta mais adequada nesse momento?",
      "opts": [
        "Diagnosticar como trabalho de parto estacionado e indicar cesariana imediata.",
        "Diagnosticar como fase latente prolongada e aguardar evolução espontânea.",
        "Realizar amniotomia para acelerar o trabalho de parto.",
        "Administrar ocitocina para aumentar a intensidade das contrações uterinas."
      ],
      "alternatives": [
        "Diagnosticar como trabalho de parto estacionado e indicar cesariana imediata.",
        "Diagnosticar como fase latente prolongada e aguardar evolução espontânea.",
        "Realizar amniotomia para acelerar o trabalho de parto.",
        "Administrar ocitocina para aumentar a intensidade das contrações uterinas."
      ],
      "answer": "B",
      "correctAnswer": "B",
      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 62. Sem revisão clínica independente.",
      "officialComment": "Primigesta com 4 cm de dilatação, colo apagado e contrações regulares, sem progressão em 4 horas, com mãe e feto bem. Pelas definições atuais da OMS e do Ministério da Saúde, a fase ativa do trabalho de parto começa aos 5 cm (6 cm pelo ACOG); com 4 cm a paciente ainda está em fase latente, cuja duração prolongada não é indicação de cesariana (A) nem de intervenção, desde que não haja sinais de comprometimento. A conduta é aguardar, com deambulação, apoio contínuo e analgesia se desejado. Amniotomia (C) e ocitocina (D) precoces aumentam intervenções sem benefício. O trabalho de parto estacionado só se diagnostica na fase ativa, com 6 cm ou mais e ausência de progressão por 4 horas com contrações adequadas.",
      "explanation": "Primigesta com 4 cm de dilatação, colo apagado e contrações regulares, sem progressão em 4 horas, com mãe e feto bem. Pelas definições atuais da OMS e do Ministério da Saúde, a fase ativa do trabalho de parto começa aos 5 cm (6 cm pelo ACOG); com 4 cm a paciente ainda está em fase latente, cuja duração prolongada não é indicação de cesariana (A) nem de intervenção, desde que não haja sinais de comprometimento. A conduta é aguardar, com deambulação, apoio contínuo e analgesia se desejado. Amniotomia (C) e ocitocina (D) precoces aumentam intervenções sem benefício. O trabalho de parto estacionado só se diagnostica na fase ativa, com 6 cm ou mais e ausência de progressão por 4 horas com contrações adequadas.",
      "sourceCommentImported": true,
