      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 93. Sem revisão clínica independente.",
      "officialComment": "Primigesta com 34 semanas e 3 dias em trabalho de parto prematuro (contrações regulares, 3 cm de dilatação, colo médio), bolsa íntegra e sem pesquisa de estreptococo do grupo B. A partir de 34 semanas não se faz tocólise, e o corticoide antenatal já não é rotina, o que descarta a alternativa B. Sem cultura para GBS, o trabalho de parto abaixo de 37 semanas é indicação de profilaxia intraparto com ampicilina ou penicilina, conduzindo-se o parto. Cesárea com sulfato de magnésio (D) não tem indicação: a neuroproteção fetal é feita abaixo de 32 semanas e a via de parto é a vaginal. A escopolamina (A) não trata trabalho de parto.",
      "explanation": "Primigesta com 34 semanas e 3 dias em trabalho de parto prematuro (contrações regulares, 3 cm de dilatação, colo médio), bolsa íntegra e sem pesquisa de estreptococo do grupo B. A partir de 34 semanas não se faz tocólise, e o corticoide antenatal já não é rotina, o que descarta a alternativa B. Sem cultura para GBS, o trabalho de parto abaixo de 37 semanas é indicação de profilaxia intraparto com ampicilina ou penicilina, conduzindo-se o parto. Cesárea com sulfato de magnésio (D) não tem indicação: a neuroproteção fetal é feita abaixo de 32 semanas e a via de parto é a vaginal. A escopolamina (A) não trata trabalho de parto.",
