      "text": "Pré-escolar, sexo feminino, 4 anos, é levada à Unidade Básica de Saúde devido à queixa de secreção vaginal esbranquiçada há 5 dias associada a prurido intenso, principalmente noturno, que faz a criança despertar. Seu irmão mais velho teve sintoma de prurido anal há 1 semana, tendo cedido após tratamento medicamentoso. Exame físico: presença de hiperemia vulvar. Dentre as seguintes alternativas, qual é o tratamento mais adequado nesse caso?",
      "statement": "Pré-escolar, sexo feminino, 4 anos, é levada à Unidade Básica de Saúde devido à queixa de secreção vaginal esbranquiçada há 5 dias associada a prurido intenso, principalmente noturno, que faz a criança despertar. Seu irmão mais velho teve sintoma de prurido anal há 1 semana, tendo cedido após tratamento medicamentoso. Exame físico: presença de hiperemia vulvar. Dentre as seguintes alternativas, qual é o tratamento mais adequado nesse caso?",
