      "officialComment": "Prurido vulvar intenso de predomínio noturno em pré-escolar, com irmão que teve prurido anal tratado há uma semana, é vulvovaginite por Enterobius vermicularis: a fêmea do oxiúro migra do ânus para a vulva à noite e leva secreção e hiperemia. O tratamento é pamoato de pirvínio em dose única, repetida após duas semanas, ou albendazol e mebendazol, com tratamento de todos os contactantes domiciliares e higiene de roupas de cama. Tiabendazol (A) é usado em larva migrans e estrongiloidíase; levamisol (C) em ascaridíase; metronidazol (D) em giardíase, tricomoníase e amebíase.",
      "explanation": "Prurido vulvar intenso de predomínio noturno em pré-escolar, com irmão que teve prurido anal tratado há uma semana, é vulvovaginite por Enterobius vermicularis: a fêmea do oxiúro migra do ânus para a vulva à noite e leva secreção e hiperemia. O tratamento é pamoato de pirvínio em dose única, repetida após duas semanas, ou albendazol e mebendazol, com tratamento de todos os contactantes domiciliares e higiene de roupas de cama. Tiabendazol (A) é usado em larva migrans e estrongiloidíase; levamisol (C) em ascaridíase; metronidazol (D) em giardíase, tricomoníase e amebíase.",
