      "answer": "B",
      "correctAnswer": "B",
      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 9. Sem revisão clínica independente.",
      "officialComment": "Tosse por dois meses sem resposta a várias medicações, perda de peso com escore z entre -2 e -3 e bom estado geral em pré-escolar exigem afastar tuberculose pulmonar. A criança não expectora, então a investigação segue o sistema de pontuação do Ministério da Saúde: radiografia de tórax, prova tuberculínica (ou IGRA), história de contato, estado nutricional, e a pesquisa microbiológica com baciloscopia, teste rápido molecular e cultura em lavado gástrico, colhido em jejum pela manhã por três dias. A tomografia (A e D) não é exame inicial. O lavado brônquico (A e C) exige broncoscopia, invasiva, e fica reservado aos casos em que o lavado gástrico não esclarece.",
      "explanation": "Tosse por dois meses sem resposta a várias medicações, perda de peso com escore z entre -2 e -3 e bom estado geral em pré-escolar exigem afastar tuberculose pulmonar. A criança não expectora, então a investigação segue o sistema de pontuação do Ministério da Saúde: radiografia de tórax, prova tuberculínica (ou IGRA), história de contato, estado nutricional, e a pesquisa microbiológica com baciloscopia, teste rápido molecular e cultura em lavado gástrico, colhido em jejum pela manhã por três dias. A tomografia (A e D) não é exame inicial. O lavado brônquico (A e C) exige broncoscopia, invasiva, e fica reservado aos casos em que o lavado gástrico não esclarece.",
      "sourceCommentImported": true,
      "commentStatus": "source-imported",
