      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 35. Sem revisão clínica independente.",
      "officialComment": "A criança teve carga viral indetectável ao nascer, aos 15 dias, 6 e 12 semanas: está exposta ao HIV, mas não infectada, e recebe o calendário completo, inclusive vacinas vivas como tríplice viral e varicela. A única adaptação é usar a vacina inativada da poliomielite em vez da oral, regra do PNI para crianças expostas ao HIV e contactantes de imunodeprimidos, hoje reforçada pela retirada da VOP do calendário. Aos 15 meses cabem DTP (primeiro reforço), VIP, hepatite A e tetraviral (SCR mais varicela), o que corresponde à alternativa D. As alternativas A e C incluem a VOP, e a B inclui febre amarela, cujo reforço é aos 4 anos.",
      "explanation": "A criança teve carga viral indetectável ao nascer, aos 15 dias, 6 e 12 semanas: está exposta ao HIV, mas não infectada, e recebe o calendário completo, inclusive vacinas vivas como tríplice viral e varicela. A única adaptação é usar a vacina inativada da poliomielite em vez da oral, regra do PNI para crianças expostas ao HIV e contactantes de imunodeprimidos, hoje reforçada pela retirada da VOP do calendário. Aos 15 meses cabem DTP (primeiro reforço), VIP, hepatite A e tetraviral (SCR mais varicela), o que corresponde à alternativa D. As alternativas A e C incluem a VOP, e a B inclui febre amarela, cujo reforço é aos 4 anos.",
