      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 78. Sem revisão clínica independente.",
      "officialComment": "Aos 4 anos o calendário do PNI prevê DTP (segundo reforço), poliomielite inativada (reforço; desde 2024 todo o esquema é feito com VIP, e a VOP foi retirada), febre amarela (reforço) e varicela (segunda dose). Como a criança nunca recebeu vacina contra influenza, a primovacinação abaixo de 9 anos é feita com duas doses com intervalo de 30 dias, e depois uma dose anual. As alternativas A e B incluem a VOP, que não é mais usada, e a A omite a febre amarela. A alternativa C erra ao prever dose única de influenza na primeira vacinação.",
      "explanation": "Aos 4 anos o calendário do PNI prevê DTP (segundo reforço), poliomielite inativada (reforço; desde 2024 todo o esquema é feito com VIP, e a VOP foi retirada), febre amarela (reforço) e varicela (segunda dose). Como a criança nunca recebeu vacina contra influenza, a primovacinação abaixo de 9 anos é feita com duas doses com intervalo de 30 dias, e depois uma dose anual. As alternativas A e B incluem a VOP, que não é mais usada, e a A omite a febre amarela. A alternativa C erra ao prever dose única de influenza na primeira vacinação.",
