      "edition": "tpi-2026-2-tpi2",
      "text": "Paciente de 2 meses, sexo masculino, foi admitido no pronto atendimento após mãe ter notado que ele estava com os lábios arroxeados. Na admissão, encontrava-se arresponsivo, com perda de tônus muscular e com respiração superficial e hipoxemia, tendo sido prontamente iniciadas ventilações assistidas. O paciente havia recebido as imunizações previstas no calendário vacinal há cerca de 5 horas e teve febre precedendo o quadro. Após cerca de 5 minutos de suporte ventilatório, o paciente apresentou recuperação da respiração e do tônus, não sendo necessária entubação orotraqueal. Ao exame de reavaliação, estava corado, hidratado, FC: 150 bpm, FR 36 irpm, PA 73x40 mmHg, pulsos presentes e simétricos, tempo de enchimento capilar de 2 segundos, com abertura ocular espontânea. Restante do exame clínico sem alterações. Com relação à investigação do evento apresentado, podemos afirmar que:",
      "statement": "Paciente de 2 meses, sexo masculino, foi admitido no pronto atendimento após mãe ter notado que ele estava com os lábios arroxeados. Na admissão, encontrava-se arresponsivo, com perda de tônus muscular e com respiração superficial e hipoxemia, tendo sido prontamente iniciadas ventilações assistidas. O paciente havia recebido as imunizações previstas no calendário vacinal há cerca de 5 horas e teve febre precedendo o quadro. Após cerca de 5 minutos de suporte ventilatório, o paciente apresentou recuperação da respiração e do tônus, não sendo necessária entubação orotraqueal. Ao exame de reavaliação, estava corado, hidratado, FC: 150 bpm, FR 36 irpm, PA 73x40 mmHg, pulsos presentes e simétricos, tempo de enchimento capilar de 2 segundos, com abertura ocular espontânea. Restante do exame clínico sem alterações. Com relação à investigação do evento apresentado, podemos afirmar que:",
