      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 95. Sem revisão clínica independente.",
      "officialComment": "Lactente de 2 meses que, cinco horas após as vacinas do calendário e com febre, apresentou hipotonia, palidez ou cianose e hiporresponsividade com recuperação completa em minutos e exame posterior normal: é o episódio hipotônico-hiporresponsivo, evento adverso conhecido da vacina pentavalente (componente pertussis), que ocorre até 48 horas após a dose e é benigno. Trata-se também de um evento breve resolvido inexplicado de baixo risco, para o qual, com exame normal, não se recomenda investigação além da notificação como evento adverso pós-vacinação; as doses seguintes podem ser feitas, preferindo a DTPa quando disponível. Pesquisa de coqueluche (B), eletrocardiograma e eletroencefalograma (A) e imagem do crânio (D) ficam para eventos recorrentes, de alto risco ou com exame alterado.",
      "explanation": "Lactente de 2 meses que, cinco horas após as vacinas do calendário e com febre, apresentou hipotonia, palidez ou cianose e hiporresponsividade com recuperação completa em minutos e exame posterior normal: é o episódio hipotônico-hiporresponsivo, evento adverso conhecido da vacina pentavalente (componente pertussis), que ocorre até 48 horas após a dose e é benigno. Trata-se também de um evento breve resolvido inexplicado de baixo risco, para o qual, com exame normal, não se recomenda investigação além da notificação como evento adverso pós-vacinação; as doses seguintes podem ser feitas, preferindo a DTPa quando disponível. Pesquisa de coqueluche (B), eletrocardiograma e eletroencefalograma (A) e imagem do crânio (D) ficam para eventos recorrentes, de alto risco ou com exame alterado.",
