      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 74. Sem revisão clínica independente.",
      "officialComment": "Recém-nascido de 36 semanas, no 10o dia, ictérico até o umbigo, que mama pouco, acorda com fome, perdeu 7% do peso de nascimento e cuja mãe tem dor nos mamilos: é icterícia por baixa ingesta de leite (icterícia da amamentação insuficiente), agravada pela prematuridade tardia. A conduta é corrigir a pega e a técnica, aumentar a frequência das mamadas e reavaliar em 24 a 48 horas, dosando a bilirrubina conforme o nomograma. Mãe A e recém-nascido O não configuram incompatibilidade ABO (A), que exige mãe O; além disso, a hemólise seria precoce. A icterícia do leite materno (B e C) ocorre em bebê que mama bem e ganha peso, e não se trata suspendendo a amamentação nem com banho de sol.",
      "explanation": "Recém-nascido de 36 semanas, no 10o dia, ictérico até o umbigo, que mama pouco, acorda com fome, perdeu 7% do peso de nascimento e cuja mãe tem dor nos mamilos: é icterícia por baixa ingesta de leite (icterícia da amamentação insuficiente), agravada pela prematuridade tardia. A conduta é corrigir a pega e a técnica, aumentar a frequência das mamadas e reavaliar em 24 a 48 horas, dosando a bilirrubina conforme o nomograma. Mãe A e recém-nascido O não configuram incompatibilidade ABO (A), que exige mãe O; além disso, a hemólise seria precoce. A icterícia do leite materno (B e C) ocorre em bebê que mama bem e ganha peso, e não se trata suspendendo a amamentação nem com banho de sol.",
