      "year": "tpi-2026-2-tpi2",
      "edition": "tpi-2026-2-tpi2",
      "text": "RN, 8 dias de vida, internado por sífilis congênita, vinha recebendo tratamento com penicilina cristalina desde o primeiro dia. Os exames laboratoriais revelaram VDRL sérico de 1:4, VDRL no líquor não reagente, líquor com proteínas totais de 69 mg/dl, 5 leucócitos/mm3 e glicose de 60 mg/dl. O raio X de ossos longos estava normal. A enfermagem informou que não estava mais conseguindo acesso vascular intravenoso periférico no bebê. Considerando as diretrizes brasileiras para o manejo dessa condição, qual é a conduta mais adequada para a finalização do tratamento?",
      "statement": "RN, 8 dias de vida, internado por sífilis congênita, vinha recebendo tratamento com penicilina cristalina desde o primeiro dia. Os exames laboratoriais revelaram VDRL sérico de 1:4, VDRL no líquor não reagente, líquor com proteínas totais de 69 mg/dl, 5 leucócitos/mm3 e glicose de 60 mg/dl. O raio X de ossos longos estava normal. A enfermagem informou que não estava mais conseguindo acesso vascular intravenoso periférico no bebê. Considerando as diretrizes brasileiras para o manejo dessa condição, qual é a conduta mais adequada para a finalização do tratamento?",
      "opts": [
        "Completar o tratamento com penicilina procaína intramuscular até o 14o dia de tratamento.",
        "Completar o tratamento com penicilina benzatina em dose única.",
        "Solicitar acesso venoso central e completar o tratamento com penicilina cristalina até o 10o dia de tratamento.",
        "Completar o tratamento com penicilina procaína intramuscular até o 10o dia de tratamento."
      ],
      "alternatives": [
        "Completar o tratamento com penicilina procaína intramuscular até o 14o dia de tratamento.",
        "Completar o tratamento com penicilina benzatina em dose única.",
        "Solicitar acesso venoso central e completar o tratamento com penicilina cristalina até o 10o dia de tratamento.",
        "Completar o tratamento com penicilina procaína intramuscular até o 10o dia de tratamento."
      ],
      "answer": "D",
