      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 91. Sem revisão clínica independente.",
      "officialComment": "Recém-nascido com sífilis congênita, VDRL sérico 1:4, líquor com VDRL não reagente, 5 leucócitos e proteína de 69 mg/dL, sem alteração óssea: não há neurossífilis, já que o protocolo considera líquor alterado com VDRL reagente, celularidade acima de 25 ou proteína acima de 150. Nessa situação o Ministério da Saúde permite tratar com penicilina cristalina intravenosa por 10 dias ou penicilina procaína intramuscular por 10 dias; perdido o acesso venoso, completa-se o esquema com procaína até totalizar 10 dias, sem reiniciar, desde que a interrupção seja inferior a 24 horas. A benzatina em dose única (B) só cabe ao recém-nascido de mãe adequadamente tratada, com exames normais. O esquema não é de 14 dias (A), e o acesso central (C) é desnecessário.",
      "explanation": "Recém-nascido com sífilis congênita, VDRL sérico 1:4, líquor com VDRL não reagente, 5 leucócitos e proteína de 69 mg/dL, sem alteração óssea: não há neurossífilis, já que o protocolo considera líquor alterado com VDRL reagente, celularidade acima de 25 ou proteína acima de 150. Nessa situação o Ministério da Saúde permite tratar com penicilina cristalina intravenosa por 10 dias ou penicilina procaína intramuscular por 10 dias; perdido o acesso venoso, completa-se o esquema com procaína até totalizar 10 dias, sem reiniciar, desde que a interrupção seja inferior a 24 horas. A benzatina em dose única (B) só cabe ao recém-nascido de mãe adequadamente tratada, com exames normais. O esquema não é de 14 dias (A), e o acesso central (C) é desnecessário.",
      "sourceCommentImported": true,
