      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 18. Sem revisão clínica independente.",
      "officialComment": "Fenilalanina de 21,5 mg/dL na triagem neonatal, com valor de referência até 1,3, é diagnóstico praticamente certo de fenilcetonúria clássica (acima de 20 mg/dL). O dano neurológico depende do tempo de exposição, por isso a dieta com fórmula metabólica isenta de fenilalanina deve começar imediatamente, idealmente antes dos 10 dias de vida, enquanto a segunda amostra confirma o resultado. Aguardar (B) perde tempo precioso. O sequenciamento do gene PAH (A) tem valor prognóstico e para aconselhamento, mas não muda a conduta inicial. A sapropterina (C) só beneficia os pacientes responsivos ao BH4, o que se testa depois de o tratamento dietético estar instituído.",
      "explanation": "Fenilalanina de 21,5 mg/dL na triagem neonatal, com valor de referência até 1,3, é diagnóstico praticamente certo de fenilcetonúria clássica (acima de 20 mg/dL). O dano neurológico depende do tempo de exposição, por isso a dieta com fórmula metabólica isenta de fenilalanina deve começar imediatamente, idealmente antes dos 10 dias de vida, enquanto a segunda amostra confirma o resultado. Aguardar (B) perde tempo precioso. O sequenciamento do gene PAH (A) tem valor prognóstico e para aconselhamento, mas não muda a conduta inicial. A sapropterina (C) só beneficia os pacientes responsivos ao BH4, o que se testa depois de o tratamento dietético estar instituído.",
