      "officialComment": "Puberdade precoce central, dependente de gonadotrofinas, em menina de 4 anos exige ressonância magnética de crânio: quanto menor a idade, maior a probabilidade de lesão orgânica do sistema nervoso central, como hamartoma hipotalâmico, glioma ou hidrocefalia. O tratamento com análogo de GnRH está indicado, mas não se associa hormônio do crescimento de rotina (A). A ultrassonografia pélvica (B) serve para investigar cisto ou tumor ovariano na puberdade periférica, independente de gonadotrofinas, que aqui já foi afastada. Observar (C) não cabe diante de progressão rápida (estágio 3 de Tanner em três meses) numa idade tão precoce.",
      "explanation": "Puberdade precoce central, dependente de gonadotrofinas, em menina de 4 anos exige ressonância magnética de crânio: quanto menor a idade, maior a probabilidade de lesão orgânica do sistema nervoso central, como hamartoma hipotalâmico, glioma ou hidrocefalia. O tratamento com análogo de GnRH está indicado, mas não se associa hormônio do crescimento de rotina (A). A ultrassonografia pélvica (B) serve para investigar cisto ou tumor ovariano na puberdade periférica, independente de gonadotrofinas, que aqui já foi afastada. Observar (C) não cabe diante de progressão rápida (estágio 3 de Tanner em três meses) numa idade tão precoce.",
