      "text": "Criança com 6 anos, feminina, apresenta desde 1 ano de idade quadros recorrentes de sibilância (4 a 5 episódios/ano). Mãe refere tosse há 12 horas. Ao exame físico observamos bom estado geral, lúcida, afebril. Frequência respiratória de 36 ipm, sem esforço respiratório. Ausculta pulmonar com sibilos expiatórios bilateralmente. Saturação de oxigênio de 96%. Qual a terapêutica inicial a ser instituída?",
      "statement": "Criança com 6 anos, feminina, apresenta desde 1 ano de idade quadros recorrentes de sibilância (4 a 5 episódios/ano). Mãe refere tosse há 12 horas. Ao exame físico observamos bom estado geral, lúcida, afebril. Frequência respiratória de 36 ipm, sem esforço respiratório. Ausculta pulmonar com sibilos expiatórios bilateralmente. Saturação de oxigênio de 96%. Qual a terapêutica inicial a ser instituída?",
