      "officialComment": "Escolar com sibilância recorrente (4 a 5 episódios por ano) chega em crise leve: fala frases, sem esforço respiratório, saturação de 96% e frequência respiratória apenas discretamente elevada. O tratamento inicial de qualquer crise de asma é o beta-2 agonista de curta ação inalatório (salbutamol por espaçador), repetido a cada 20 minutos na primeira hora conforme a resposta. A via oral (B) é menos eficaz, mais lenta e dá mais taquicardia e tremor. O corticoide inalatório (C) é medicação de controle, que esta criança de fato precisa iniciar pela recorrência, mas não trata a crise. O corticoide oral (D) entra nas crises moderadas e graves ou quando não há resposta ao broncodilatador, não como primeira medida numa crise leve.",
      "explanation": "Escolar com sibilância recorrente (4 a 5 episódios por ano) chega em crise leve: fala frases, sem esforço respiratório, saturação de 96% e frequência respiratória apenas discretamente elevada. O tratamento inicial de qualquer crise de asma é o beta-2 agonista de curta ação inalatório (salbutamol por espaçador), repetido a cada 20 minutos na primeira hora conforme a resposta. A via oral (B) é menos eficaz, mais lenta e dá mais taquicardia e tremor. O corticoide inalatório (C) é medicação de controle, que esta criança de fato precisa iniciar pela recorrência, mas não trata a crise. O corticoide oral (D) entra nas crises moderadas e graves ou quando não há resposta ao broncodilatador, não como primeira medida numa crise leve.",
