      "edition": "tpi-2026-2-tpi2",
      "text": "Menina, 3 anos de idade, hígida, há 2 dias apresenta evacuações líquidas com raias de sangue, sem febre ou dor abdominal. Exame físico sem alterações. Considerando o diagnóstico, além de manter a alimentação habitual e aumentar a oferta de líquidos ou soro de reidratação oral após cada evacuação diarreica, qual é a orientação adicional recomendada pelo Ministério da Saúde?",
      "statement": "Menina, 3 anos de idade, hígida, há 2 dias apresenta evacuações líquidas com raias de sangue, sem febre ou dor abdominal. Exame físico sem alterações. Considerando o diagnóstico, além de manter a alimentação habitual e aumentar a oferta de líquidos ou soro de reidratação oral após cada evacuação diarreica, qual é a orientação adicional recomendada pelo Ministério da Saúde?",
