      "officialComment": "Diarreia aguda de dois dias com raias de sangue, sem febre, sem dor e sem desidratação, em pré-escolar hígida, é tratada com o plano A do Ministério da Saúde: manter a alimentação, aumentar líquidos e soro de reidratação oral após cada evacuação, orientar os sinais de alarme e prescrever zinco por 10 a 14 dias (20 mg ao dia acima de 6 meses), que reduz a duração e a recorrência. Coprocultura (A) não é rotina. Probiótico (B) não consta das recomendações do Ministério. Antibiótico (D) fica reservado à disenteria com comprometimento do estado geral, febre alta, imunossupressão ou suspeita de cólera, e a azitromicina não é a primeira escolha.",
      "explanation": "Diarreia aguda de dois dias com raias de sangue, sem febre, sem dor e sem desidratação, em pré-escolar hígida, é tratada com o plano A do Ministério da Saúde: manter a alimentação, aumentar líquidos e soro de reidratação oral após cada evacuação, orientar os sinais de alarme e prescrever zinco por 10 a 14 dias (20 mg ao dia acima de 6 meses), que reduz a duração e a recorrência. Coprocultura (A) não é rotina. Probiótico (B) não consta das recomendações do Ministério. Antibiótico (D) fica reservado à disenteria com comprometimento do estado geral, febre alta, imunossupressão ou suspeita de cólera, e a azitromicina não é a primeira escolha.",
