      "answerStatus": "supplied-pdf-key",
      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 68. Sem revisão clínica independente.",
      "officialComment": "Pressão de 135 por 90 em três ocasiões em adolescente de 12 anos configura hipertensão (a partir dos 13 anos usam-se os cortes do adulto, 130 por 80). Entre os fatores listados, o único modificável é a obesidade, com IMC acima do percentil 95, que é a principal causa de hipertensão primária na adolescência e responde à mudança de estilo de vida. Baixo peso ao nascer (A) e prematuridade são fatores de risco, mas não podem ser alterados. O TDAH (B) em si não causa hipertensão, embora os estimulantes possam elevar a pressão. O estirão (D) é fisiológico. A investigação de causas secundárias segue conforme a idade e o exame.",
      "explanation": "Pressão de 135 por 90 em três ocasiões em adolescente de 12 anos configura hipertensão (a partir dos 13 anos usam-se os cortes do adulto, 130 por 80). Entre os fatores listados, o único modificável é a obesidade, com IMC acima do percentil 95, que é a principal causa de hipertensão primária na adolescência e responde à mudança de estilo de vida. Baixo peso ao nascer (A) e prematuridade são fatores de risco, mas não podem ser alterados. O TDAH (B) em si não causa hipertensão, embora os estimulantes possam elevar a pressão. O estirão (D) é fisiológico. A investigação de causas secundárias segue conforme a idade e o exame.",
