      "text": "Menino, 5 anos de idade, apresenta febre de até 39,2°C há 72 horas, de difícil controle com antitérmicos, sem sintomas respiratórios ou gastrointestinais, além de diminuição da aceitação alimentar e irritabilidade. Exame físico: não postectomizado. Exames laboratoriais: urina tipo 1: pH = 7, densidade = 1015, leucócitos = 380.000/mL, hemácias = 10.000/mL, nitrito e bactérias positivos; hemograma com neutrofilia e desvio à esquerda, hemoglobina e plaquetas normais. Ultrassonografia de rins e vias urinárias com presença de cálculo coraliforme ocupando a pelve renal direita. Qual é o agente etiológico mais provável para este paciente?",
