      "officialComment": "Infecção urinária febril em menino de 5 anos com cálculo coraliforme e urina de pH 7 aponta para bactéria produtora de urease: a urease hidrolisa a ureia em amônia, alcaliniza a urina e precipita fosfato amoníaco-magnesiano (estruvita), formando o cálculo coraliforme. O agente clássico é Proteus mirabilis. Escherichia coli (B) é o agente mais comum de infecção urinária em geral, mas não produz urease. Klebsiella (A) também pode produzir urease, mas é muito menos associada a cálculo de estruvita. Staphylococcus saprophyticus (C) causa cistite em mulheres jovens sexualmente ativas.",
      "explanation": "Infecção urinária febril em menino de 5 anos com cálculo coraliforme e urina de pH 7 aponta para bactéria produtora de urease: a urease hidrolisa a ureia em amônia, alcaliniza a urina e precipita fosfato amoníaco-magnesiano (estruvita), formando o cálculo coraliforme. O agente clássico é Proteus mirabilis. Escherichia coli (B) é o agente mais comum de infecção urinária em geral, mas não produz urease. Klebsiella (A) também pode produzir urease, mas é muito menos associada a cálculo de estruvita. Staphylococcus saprophyticus (C) causa cistite em mulheres jovens sexualmente ativas.",
