      "edition": "tpi-2026-2-tpi2",
      "text": "Paciente do sexo masculino, 10 anos, é atendido na unidade básica de saúde com queixa de urina avermelhada há dois dias; nega febre, disúria ou queixas abdominais. Refere ter apresentado episódio de faringoamigdalite há aproximadamente 2 semanas, tratado ambulatorialmente. Ao exame físico, apresenta edema palpebral discreto (1+/4+) e pressão arterial de 130 x 85 mmHg, compatível com valores acima do percentil 95 para idade. Foram solicitados exames complementares, e o paciente permanece em acompanhamento na unidade. Com base na hipótese diagnóstica mais provável, assinale a alternativa correta.",
      "statement": "Paciente do sexo masculino, 10 anos, é atendido na unidade básica de saúde com queixa de urina avermelhada há dois dias; nega febre, disúria ou queixas abdominais. Refere ter apresentado episódio de faringoamigdalite há aproximadamente 2 semanas, tratado ambulatorialmente. Ao exame físico, apresenta edema palpebral discreto (1+/4+) e pressão arterial de 130 x 85 mmHg, compatível com valores acima do percentil 95 para idade. Foram solicitados exames complementares, e o paciente permanece em acompanhamento na unidade. Com base na hipótese diagnóstica mais provável, assinale a alternativa correta.",
