      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 19. Sem revisão clínica independente.",
      "officialComment": "Hematúria macroscópica, edema palpebral e hipertensão duas semanas após faringoamigdalite em escolar caracterizam glomerulonefrite pós-estreptocócica. A hematúria microscópica pode persistir por até um a dois anos sem indicar mau prognóstico; o que preocupa é proteinúria persistente ou queda da função renal. A hipocomplementemia (B) é típica, com C3 baixo que normaliza em 6 a 8 semanas, mas não é patognomônica: ocorre no lúpus, na membranoproliferativa e na endocardite. Depósitos mesangiais de IgA (C) definem a nefropatia por IgA; na pós-estreptocócica há depósitos granulares de C3 e IgG com as corcovas subepiteliais. A hematúria glomerular (D) é de hemácias dismórficas, não isomórficas.",
      "explanation": "Hematúria macroscópica, edema palpebral e hipertensão duas semanas após faringoamigdalite em escolar caracterizam glomerulonefrite pós-estreptocócica. A hematúria microscópica pode persistir por até um a dois anos sem indicar mau prognóstico; o que preocupa é proteinúria persistente ou queda da função renal. A hipocomplementemia (B) é típica, com C3 baixo que normaliza em 6 a 8 semanas, mas não é patognomônica: ocorre no lúpus, na membranoproliferativa e na endocardite. Depósitos mesangiais de IgA (C) definem a nefropatia por IgA; na pós-estreptocócica há depósitos granulares de C3 e IgG com as corcovas subepiteliais. A hematúria glomerular (D) é de hemácias dismórficas, não isomórficas.",
