      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 8. Sem revisão clínica independente.",
      "officialComment": "No transtorno do espectro autista, o que mais modifica o desfecho é a intervenção precoce, intensiva e estruturada, baseada em princípios comportamentais (ABA, modelos naturalistas como o ESDM), com treinamento dos pais para que as estratégias continuem em casa; é o que recomendam AAP e NICE. A fonoaudiologia (B) faz parte do plano, mas isoladamente não responde ao déficit central de comunicação social. A risperidona (C) tem indicação apenas para irritabilidade grave e agressividade que não respondem a medidas comportamentais, não como conduta inicial. Aguardar a evolução (D) desperdiça a janela de maior plasticidade cerebral, justamente quando a intervenção rende mais.",
      "explanation": "No transtorno do espectro autista, o que mais modifica o desfecho é a intervenção precoce, intensiva e estruturada, baseada em princípios comportamentais (ABA, modelos naturalistas como o ESDM), com treinamento dos pais para que as estratégias continuem em casa; é o que recomendam AAP e NICE. A fonoaudiologia (B) faz parte do plano, mas isoladamente não responde ao déficit central de comunicação social. A risperidona (C) tem indicação apenas para irritabilidade grave e agressividade que não respondem a medidas comportamentais, não como conduta inicial. Aguardar a evolução (D) desperdiça a janela de maior plasticidade cerebral, justamente quando a intervenção rende mais.",
