      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 89. Sem revisão clínica independente.",
      "officialComment": "Os atributos da APS descritos por Starfield incluem a longitudinalidade, o acompanhamento ao longo do tempo por uma mesma equipe, que depende da adscrição da população a um território. Para o seguimento de uma condição crônica como a hipercolesterolemia, a unidade da área de moradia é o local adequado, e a orientação da recepção está correta nesse sentido. A alternativa B erra ao afirmar que pessoas não cadastradas não podem ser atendidas: demandas agudas e urgências devem ser acolhidas em qualquer unidade. A alternativa A inventa uma regra de atendimento a familiares fora do território. A universalidade (D) garante o acesso ao sistema, não a escolha de qualquer unidade para cuidado longitudinal.",
      "explanation": "Os atributos da APS descritos por Starfield incluem a longitudinalidade, o acompanhamento ao longo do tempo por uma mesma equipe, que depende da adscrição da população a um território. Para o seguimento de uma condição crônica como a hipercolesterolemia, a unidade da área de moradia é o local adequado, e a orientação da recepção está correta nesse sentido. A alternativa B erra ao afirmar que pessoas não cadastradas não podem ser atendidas: demandas agudas e urgências devem ser acolhidas em qualquer unidade. A alternativa A inventa uma regra de atendimento a familiares fora do território. A universalidade (D) garante o acesso ao sistema, não a escolha de qualquer unidade para cuidado longitudinal.",
