      "text": "Mulher de 56 anos apresenta dor na coluna lombar irradiada para membro inferior direito, iniciada há várias semanas, intensidade 6/10, com piora à mobilização do membro, acompanhada de sensação de choques no pé ipsilateral e às vezes formigamentos nos dedos do pé. AP: carcinoma de mama com metástases ósseas disseminadas, em tratamento com hormonioterapia paliativa e radioterapia prévia em coluna (L3-L4-L5) há 1 ano. Ao exame físico: discreta alteração de sensibilidade do membro inferior direito, sem déficit motor. O diagnóstico etiológico da dor e a estratégia para o controle dos sintomas são, respectivamente:",
      "statement": "Mulher de 56 anos apresenta dor na coluna lombar irradiada para membro inferior direito, iniciada há várias semanas, intensidade 6/10, com piora à mobilização do membro, acompanhada de sensação de choques no pé ipsilateral e às vezes formigamentos nos dedos do pé. AP: carcinoma de mama com metástases ósseas disseminadas, em tratamento com hormonioterapia paliativa e radioterapia prévia em coluna (L3-L4-L5) há 1 ano. Ao exame físico: discreta alteração de sensibilidade do membro inferior direito, sem déficit motor. O diagnóstico etiológico da dor e a estratégia para o controle dos sintomas são, respectivamente:",
