      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 17. Sem revisão clínica independente.",
      "officialComment": "Dor lombar irradiada para o membro inferior, com choques e formigamento no pé e alteração de sensibilidade, em paciente com metástases ósseas na coluna lombar, é dor neuropática por radiculopatia compressiva metastática. O tratamento combina adjuvantes para dor neuropática, antidepressivo tricíclico ou gabapentinoide, e corticoide para o componente compressivo, associados ou não a opioide, além de avaliar radioterapia da lesão. A plexopatia por radioterapia prévia (A) é rara, tardia e não teria padrão radicular unilateral com metástases conhecidas no local. A dor óssea metastática (B) é profunda, em peso, sem distribuição radicular. O plexo celíaco (D) medeia dor visceral abdominal, não dor no membro inferior.",
      "explanation": "Dor lombar irradiada para o membro inferior, com choques e formigamento no pé e alteração de sensibilidade, em paciente com metástases ósseas na coluna lombar, é dor neuropática por radiculopatia compressiva metastática. O tratamento combina adjuvantes para dor neuropática, antidepressivo tricíclico ou gabapentinoide, e corticoide para o componente compressivo, associados ou não a opioide, além de avaliar radioterapia da lesão. A plexopatia por radioterapia prévia (A) é rara, tardia e não teria padrão radicular unilateral com metástases conhecidas no local. A dor óssea metastática (B) é profunda, em peso, sem distribuição radicular. O plexo celíaco (D) medeia dor visceral abdominal, não dor no membro inferior.",
