      "text": "Mulher de 28 anos chega à unidade de pronto atendimento vítima de múltiplos ferimentos por arma branca há 30 minutos, evoluindo a óbito após 3 horas, mesmo após ser submetida a cirurgia de emergência e receber todos os cuidados necessários. Dentre os exames laboratoriais. foi constatado teste de gravidez positivo. Como a instituição deve notificar esse óbito?",
      "statement": "Mulher de 28 anos chega à unidade de pronto atendimento vítima de múltiplos ferimentos por arma branca há 30 minutos, evoluindo a óbito após 3 horas, mesmo após ser submetida a cirurgia de emergência e receber todos os cuidados necessários. Dentre os exames laboratoriais. foi constatado teste de gravidez positivo. Como a instituição deve notificar esse óbito?",
