      "officialComment": "Morte materna é a morte de mulher durante a gestação ou até 42 dias após o seu término, por qualquer causa relacionada ou agravada pela gravidez, excluídas as causas acidentais ou incidentais. A morte por agressão com arma branca é causa externa, portanto morte materna não obstétrica: deve ser notificada e investigada pela vigilância do óbito de mulher em idade fértil, mas não entra no numerador da razão de mortalidade materna. A morte obstétrica direta (B) decorre de complicações da gravidez, parto ou puerpério, como hemorragia e hipertensão; a indireta (C) decorre de doença prévia agravada pela gestação. A alternativa D erra ao negar a condição de morte materna, que existe na classificação, apenas na categoria não obstétrica.",
      "explanation": "Morte materna é a morte de mulher durante a gestação ou até 42 dias após o seu término, por qualquer causa relacionada ou agravada pela gravidez, excluídas as causas acidentais ou incidentais. A morte por agressão com arma branca é causa externa, portanto morte materna não obstétrica: deve ser notificada e investigada pela vigilância do óbito de mulher em idade fértil, mas não entra no numerador da razão de mortalidade materna. A morte obstétrica direta (B) decorre de complicações da gravidez, parto ou puerpério, como hemorragia e hipertensão; a indireta (C) decorre de doença prévia agravada pela gestação. A alternativa D erra ao negar a condição de morte materna, que existe na classificação, apenas na categoria não obstétrica.",
