      "text": "Um estudo teve como objetivo examinar o impacto da pandemia de covid-19 na prescrição de antibióticos. Foram utilizados dados nacionais de distribuição de antibióticos entre 2014 e 2020, estratificados por idade, sexo e especialidade do médico prescritor. Os resultados do estudo apontam que, ajustando para o efeito da sazonalidade, a taxa de distribuição de antibióticos no país em estudo diminuiu 26,5% durante os primeiros 8 meses da pandemia de covid-19 no país, em comparação com o período anterior à pandemia. O desenho de estudo foi",
