      "officialComment": "O estudo comparou taxas de distribuição de antibióticos em um país inteiro, em períodos antes e durante a pandemia, ajustando sazonalidade. A unidade de análise é a população agregada, não o indivíduo, e a exposição e o desfecho são medidos em nível coletivo: é um estudo ecológico, aqui do tipo série temporal. O transversal (A) e a coorte (C) medem exposição e desfecho em indivíduos. Chamá-lo apenas de descritivo (B) é insuficiente, porque há comparação entre períodos com hipótese de impacto, o que o torna analítico. A limitação clássica é a falácia ecológica: o que vale para o agregado pode não valer para cada pessoa.",
