      "officialComment": "Comparar taxas brutas de perda de seguimento de dois serviços não permite concluir sobre a qualidade da assistência, porque as populações podem diferir em características que influenciam o abandono: gravidade da doença, coinfecção por HIV, uso de álcool e drogas, situação de rua, escolaridade. Essas variáveis confundem a comparação, e o ajuste por elas é necessário antes de qualquer julgamento, o que invalida as alternativas C e D. Conhecer as taxas de cura (B) acrescenta informação, mas não resolve o confundimento; a comparação continuaria enviesada.",
