      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 36. Sem revisão clínica independente.",
      "officialComment": "Na teleconsultoria e na teleinterconsulta, reguladas pela Resolução CFM 2.314/2022, o médico assistente mantém a responsabilidade pelo paciente e pela execução das condutas, enquanto o especialista remoto responde pelas orientações que forneceu; a responsabilidade é solidária, cada um na sua esfera de atuação e decisão, e ambos têm o dever de registrar em prontuário o que foi orientado e feito. A alternativa C erra ao negar vínculo do consultor, que assume responsabilidade técnica pelo que orienta. As alternativas B e D atribuem responsabilidade exclusiva a um dos dois, o que contraria a norma. A falha de registro do médico local agrava a sua posição, mas não exclui a do especialista.",
      "explanation": "Na teleconsultoria e na teleinterconsulta, reguladas pela Resolução CFM 2.314/2022, o médico assistente mantém a responsabilidade pelo paciente e pela execução das condutas, enquanto o especialista remoto responde pelas orientações que forneceu; a responsabilidade é solidária, cada um na sua esfera de atuação e decisão, e ambos têm o dever de registrar em prontuário o que foi orientado e feito. A alternativa C erra ao negar vínculo do consultor, que assume responsabilidade técnica pelo que orienta. As alternativas B e D atribuem responsabilidade exclusiva a um dos dois, o que contraria a norma. A falha de registro do médico local agrava a sua posição, mas não exclui a do especialista.",
