      "officialComment": "8142) A Constituição, no artigo 199, e a Lei 8.080, nos artigos 24 a 26, estabelecem que, quando as disponibilidades do SUS forem insuficientes, ele pode recorrer aos serviços privados, mediante contrato ou convênio, em caráter complementar, com preferência para entidades filantrópicas e sem fins lucrativos. É exatamente o mecanismo da compra de capacidade ociosa de hospitais privados descrito no programa. O setor suplementar (D) é o dos planos e seguros de saúde, regidos pela Lei 9.656. Organização social (A) é um modelo de gestão de unidades públicas por entidade privada qualificada. Prestador subsidiário (B) não é figura prevista na legislação.",
      "explanation": "8142) A Constituição, no artigo 199, e a Lei 8.080, nos artigos 24 a 26, estabelecem que, quando as disponibilidades do SUS forem insuficientes, ele pode recorrer aos serviços privados, mediante contrato ou convênio, em caráter complementar, com preferência para entidades filantrópicas e sem fins lucrativos. É exatamente o mecanismo da compra de capacidade ociosa de hospitais privados descrito no programa. O setor suplementar (D) é o dos planos e seguros de saúde, regidos pela Lei 9.656. Organização social (A) é um modelo de gestão de unidades públicas por entidade privada qualificada. Prestador subsidiário (B) não é figura prevista na legislação.",
