      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 96. Sem revisão clínica independente.",
      "officialComment": "Gestante de 18 anos em situação de rua, sem documentos, sem pré-natal e com histórico de violência ao buscar serviços, atendida pelo Consultório na Rua. A resposta é intersetorial: cadastro na UBS de referência do território onde ela vive, pois não se exige comprovante de residência, acionamento da assistência social (Centro POP, CREAS) e de organizações da sociedade civil, e encaminhamento ao pré-natal de alto risco pela vulnerabilidade, desnutrição e ausência de pré-natal. A internação compulsória em comunidade terapêutica (A) viola direitos e não tem indicação. Criar uma rede que exclua a UBS (C) contraria o modelo de atenção. Responsabilizar a paciente pela adesão (D) ignora a vulnerabilidade que a afasta dos serviços.",
      "explanation": "Gestante de 18 anos em situação de rua, sem documentos, sem pré-natal e com histórico de violência ao buscar serviços, atendida pelo Consultório na Rua. A resposta é intersetorial: cadastro na UBS de referência do território onde ela vive, pois não se exige comprovante de residência, acionamento da assistência social (Centro POP, CREAS) e de organizações da sociedade civil, e encaminhamento ao pré-natal de alto risco pela vulnerabilidade, desnutrição e ausência de pré-natal. A internação compulsória em comunidade terapêutica (A) viola direitos e não tem indicação. Criar uma rede que exclua a UBS (C) contraria o modelo de atenção. Responsabilizar a paciente pela adesão (D) ignora a vulnerabilidade que a afasta dos serviços.",
