      "text": "Leia o texto a seguir: \" ́Olá, M.Z.T.! Esperamos que esteja bem! Viemos aqui hoje trazer uma notícia do seu plano de saúde. Por decisão da operadora desse plano e, apesar de todos os nossos esforços para a manutenção da sua permanência, ele será cancelado a partir de 1o de maio de 2024. ́ Foi por meio dessa mensagem que o engenheiro mecânico J.T. F. soube, no dia 28 de março, que o plano de saúde da mãe dele, M.Z.T., seria rescindido pela operadora 32 dias depois. M.Z.T. tem 102 anos.\" Texto extraído de notícia publicada no Jornal Folha de S. Paulo em 16/04/2024. Adaptado. A notícia retrata uma prática recorrente dos planos e seguros de saúde no Brasil, que é a rescisão unilateral imotivada de contratos por parte das operadoras do setor. Assinale a alternativa correta sobre a rescisão unilateral imotivada por parte dos planos de saúde.",
      "statement": "Leia o texto a seguir: \" ́Olá, M.Z.T.! Esperamos que esteja bem! Viemos aqui hoje trazer uma notícia do seu plano de saúde. Por decisão da operadora desse plano e, apesar de todos os nossos esforços para a manutenção da sua permanência, ele será cancelado a partir de 1o de maio de 2024. ́ Foi por meio dessa mensagem que o engenheiro mecânico J.T. F. soube, no dia 28 de março, que o plano de saúde da mãe dele, M.Z.T., seria rescindido pela operadora 32 dias depois. M.Z.T. tem 102 anos.\" Texto extraído de notícia publicada no Jornal Folha de S. Paulo em 16/04/2024. Adaptado. A notícia retrata uma prática recorrente dos planos e seguros de saúde no Brasil, que é a rescisão unilateral imotivada de contratos por parte das operadoras do setor. Assinale a alternativa correta sobre a rescisão unilateral imotivada por parte dos planos de saúde.",
