      "answerNote": "Gabarito e comentários transcritos do PDF fornecido. Alternativas A–D na ordem deste material, sem a opção Não marcar. Caderno 1: questão 14. Sem revisão clínica independente.",
      "officialComment": "A Lei 9.656/98 só permite a rescisão unilateral pela operadora nos planos individuais e familiares em caso de fraude ou inadimplência superior a 60 dias. Nos contratos coletivos, empresariais ou por adesão, a lei não veda a rescisão imotivada, e as normas da ANS a admitem após 12 meses de vigência, com aviso prévio de 60 dias; é essa brecha que a notícia retrata, hoje combatida em decisões do STJ que exigem justificativa quando há idoso ou tratamento em curso. O Estatuto do Idoso (A) não trata do tema. As cooperativas médicas (B) seguem as mesmas regras das demais operadoras. A alternativa C generaliza uma proibição que só vale para o contrato individual.",
      "explanation": "A Lei 9.656/98 só permite a rescisão unilateral pela operadora nos planos individuais e familiares em caso de fraude ou inadimplência superior a 60 dias. Nos contratos coletivos, empresariais ou por adesão, a lei não veda a rescisão imotivada, e as normas da ANS a admitem após 12 meses de vigência, com aviso prévio de 60 dias; é essa brecha que a notícia retrata, hoje combatida em decisões do STJ que exigem justificativa quando há idoso ou tratamento em curso. O Estatuto do Idoso (A) não trata do tema. As cooperativas médicas (B) seguem as mesmas regras das demais operadoras. A alternativa C generaliza uma proibição que só vale para o contrato individual.",
